import { useState, useEffect, useRef, memo, useCallback, useMemo, Component, lazy, Suspense } from "react";
import { createPortal } from "react-dom";
import { DndContext, PointerSensor, TouchSensor, KeyboardSensor, useSensor, useSensors, closestCenter } from "@dnd-kit/core";
import { SortableContext, useSortable, verticalListSortingStrategy, arrayMove, sortableKeyboardCoordinates } from "@dnd-kit/sortable";
import { CSS } from "@dnd-kit/utilities";

// ═════════════════════════════════════════════════════════════════════════════
// DURABLE NATIVE STORAGE
// localStorage in an iOS WKWebView is NOT durable — iOS can evict it under storage
// pressure, which would wipe a user's local workout state. This layer makes the app's
// state survive that by mirroring every localStorage write to the native Capacitor
// Preferences store (real on-device storage), and restoring from it at launch.
//
// Design choice (deliberately low-risk): the app keeps using synchronous `localStorage`
// exactly as before — we don't touch the ~30 call sites. We just (1) hydrate localStorage
// from native Preferences ONCE at startup (before React renders), and (2) transparently
// mirror writes/removes to native in the background by wrapping setItem/removeItem.
// If Preferences is empty on first run (existing users), localStorage already has their
// data and we seed Preferences from it — so nothing is ever lost in the transition.
// ═════════════════════════════════════════════════════════════════════════════
function nativePrefs() {
  const Cap = (typeof window !== "undefined") ? window.Capacitor : null;
  if (Cap?.isNativePlatform?.() && Cap.Plugins?.Preferences) return Cap.Plugins.Preferences;
  return null;
}

// Keys we mirror to native storage. We only persist the app's real state — not transient
// caches. (Anything not listed still works in localStorage; it just isn't durably backed.)
const DURABLE_PREFIX = "seshd_";

// Install the write-through mirror ONCE. After this, every localStorage.setItem/removeItem
// for a seshd_* key also updates native storage. Idempotent.
let __mirrorInstalled = false;
function installStorageMirror() {
  if (__mirrorInstalled || typeof window === "undefined" || !window.localStorage) return;
  if (!nativePrefs()) return; // web build / not native — plain localStorage is fine
  // MUST patch Storage.prototype, not the localStorage instance: per the web storage spec,
  // `localStorage.setItem = fn` does NOT override the method — Storage objects route property
  // assignments into stored ITEMS and the prototype method stays. The instance-assignment
  // version of this mirror was a silent no-op in every real browser/WebView.
  const proto = window.Storage && window.Storage.prototype;
  if (!proto || typeof proto.setItem !== "function") return;
  __mirrorInstalled = true;
  const origSet = proto.setItem;
  const origRemove = proto.removeItem;
  proto.setItem = function (key, value) {
    origSet.call(this, key, value);
    if (this === window.localStorage && typeof key === "string" && key.startsWith(DURABLE_PREFIX)) {
      try { nativePrefs()?.set({ key, value: String(value) }).catch(() => {}); } catch {}
    }
  };
  proto.removeItem = function (key) {
    origRemove.call(this, key);
    if (this === window.localStorage && typeof key === "string" && key.startsWith(DURABLE_PREFIX)) {
      try { nativePrefs()?.remove({ key }).catch(() => {}); } catch {}
    }
  };
}

// Hydrate localStorage from native Preferences at startup. MUST be awaited before the app
// reads localStorage (i.e. before React mounts) so loadStore()/loadSession() see real data.
// - If native has data: copy it into localStorage (this is the durable source of truth).
// - If native is empty but localStorage has data (existing user's first run on this build):
//   seed native from localStorage so it's protected from here on.
// Exported so the app entry (main.jsx) can `await hydrateFromNative()` BEFORE mounting React,
// ensuring localStorage is populated from durable native storage before loadStore() runs.
export { hydrateFromNative };

async function hydrateFromNative() {
  const P = nativePrefs();
  if (!P) return; // web / non-native — localStorage is already the store
  try {
    const { keys } = await P.keys();
    const nativeKeys = (keys || []).filter(k => typeof k === "string" && k.startsWith(DURABLE_PREFIX));
    if (nativeKeys.length > 0) {
      // Native is the source of truth — pull everything into localStorage.
      for (const key of nativeKeys) {
        try {
          const { value } = await P.get({ key });
          if (value != null) localStorage.setItem(key, value);
        } catch {}
      }
    } else {
      // First run with native storage available — seed it from whatever localStorage has.
      try {
        for (let i = 0; i < localStorage.length; i++) {
          const key = localStorage.key(i);
          if (key && key.startsWith(DURABLE_PREFIX)) {
            const value = localStorage.getItem(key);
            if (value != null) await P.set({ key, value });
          }
        }
      } catch {}
    }
  } catch {}
  // Install the write-through mirror AFTER hydration so we don't echo during restore.
  installStorageMirror();
  // Session tokens: hydrate from / migrate into the iOS Keychain (no-op on web or until
  // the secure-storage plugin has been synced into the native build).
  await hydrateSessionFromKeychain();
}


export const SUPABASE_URL = import.meta.env.VITE_SUPABASE_URL;
export const SUPABASE_KEY = import.meta.env.VITE_SUPABASE_ANON_KEY;
const IS_DEV = !!(import.meta.env && import.meta.env.DEV); // true in `vite dev`, false in production builds
export const NAV_CLEARANCE = "calc(86px + env(safe-area-inset-bottom))"; // bottom-padding so scrollable content clears the floating bottom nav overlay
export const devWarn = (...args) => { if (IS_DEV) console.warn(...args); };
export const devError = (...args) => { if (IS_DEV) console.error(...args); };

// ── Auth callback fragment ────────────────────────────────────────────────────
// OAuth callbacks and password-recovery links both land with the tokens in the URL FRAGMENT
// (#access_token=…&refresh_token=…&type=recovery). Capture them and strip the fragment HERE, at
// module load, before a single component mounts or any third-party script initialises.
//
// This is a takeover-prevention measure, not tidiness. A recovery fragment carries a LIVE
// access_token and refresh_token for the account — whoever holds them owns it. PostHog's
// automatic pageview capture reads window.location.href verbatim into `$current_url`, and it
// fires on load; the boot code that used to clear the fragment ran inside a React effect, after
// an `await fetch` to /auth/v1/user. That window was wide enough to hand a working account
// takeover to a third-party analytics store for every user who ever reset a password. PostHog is
// currently unconfigured, so it never happened — this closes the door before it can.
//
// Anything downstream must read AUTH_CALLBACK, never window.location.hash. Other hash routes
// (#/u/<username>) don't contain access_token and are left untouched.
const AUTH_CALLBACK = (() => {
  try {
    if (typeof window === "undefined") return null;
    const h = window.location.hash || "";
    if (!h.includes("access_token=")) return null;
    const params = new URLSearchParams(h.slice(1));
    window.history.replaceState(null, "", window.location.pathname + window.location.search);
    return params;
  } catch { return null; }
})();

// ── Analytics (PostHog) ────────────────────────────────────────────────────────
// No-op until VITE_POSTHOG_KEY is set in Vercel env vars. We send behavioral
// events only (signup, workout logged, post created, tab switches) — never
// workout content, photos, or messages — to keep this purely usage analytics.
const POSTHOG_KEY = import.meta.env.VITE_POSTHOG_KEY || "";
export function track(event, props = {}) {
  try {
    if (!POSTHOG_KEY || typeof window === "undefined" || !window.posthog) return;
    window.posthog.capture(event, props);
  } catch (e) {}
}
function identifyUser(userId) {
  try {
    if (!POSTHOG_KEY || typeof window === "undefined" || !window.posthog || !userId) return;
    window.posthog.identify(userId);
  } catch (e) {}
}

// ── OAuth provider flags ──────────────────────────────────────────────────────
// Flip a provider to true ONLY after it's fully configured in Supabase
// (Auth → Providers). An unconfigured provider renders a login button that fails
// on tap — App Review taps every button, and a dead login is a rejection.
export const OAUTH_ENABLED = { apple: false, google: false };

// Lightweight Supabase client — no npm package needed
const sb = (() => {
  const headers = {
    "apikey": SUPABASE_KEY,
    "Authorization": `Bearer ${SUPABASE_KEY}`,
    "Content-Type": "application/json",
    "Prefer": "return=representation",
  };

  function authHeaders(token) {
    if (!token) return headers;
    return { ...headers, "Authorization": `Bearer ${token}` };
  }

  async function query(path, opts = {}, token = null) {
    const { headers_extra, timeout, ...fetchOpts } = opts;
    const mergedHeaders = { ...authHeaders(token), ...(headers_extra || {}) };
    // Hard timeout so a stalled connection can never hang a screen forever (e.g. the Messages
    // list spinning indefinitely on a flaky network). AbortController alone isn't enough on
    // native: CapacitorHttp's patched fetch ignores `signal`, so we also race a manual timer that
    // rejects. Whichever fires, the rejection is flagged `transportFailure` in the catch below.
    const ms = timeout || 20000;
    const ctrl = new AbortController();
    let timeoutId;
    const timeoutP = new Promise((_, rej) => {
      timeoutId = setTimeout(() => { ctrl.abort(); rej(new Error("Request timed out")); }, ms);
    });
    let res;
    try {
      res = await Promise.race([
        fetch(`${SUPABASE_URL}/rest/v1/${path}`, { headers: mergedHeaders, signal: ctrl.signal, ...fetchOpts }),
        timeoutP,
      ]);
    } catch (e) {
      // fetch rejected (offline / DNS / CORS / aborted) or we timed out — the request never
      // returned a response, so it's a transport failure the caller can safely re-queue/retry.
      // Flag it explicitly: under CapacitorHttp native transport errors reject as a generic Error
      // (name "Error"), not a TypeError, so sniffing e.name is no longer reliable.
      if (e) e.transportFailure = true;
      throw e;
    } finally {
      clearTimeout(timeoutId);
    }
    if (!res.ok) {
      const err = await res.json().catch(() => ({}));
      const e = new Error(err.message || res.statusText);
      e.httpStatus = res.status; // the server responded — this is NOT a transport failure
      throw e;
    }
    const text = await res.text();
    return text ? JSON.parse(text) : null;
  }

  async function rpc(fn, params = {}, token = null) {
    const res = await fetch(`${SUPABASE_URL}/rest/v1/rpc/${fn}`, {
      method: "POST",
      headers: authHeaders(token),
      body: JSON.stringify(params),
    });
    if (!res.ok) {
      const err = await res.json().catch(() => ({}));
      throw new Error(err.message || res.statusText);
    }
    const text = await res.text();
    return text ? JSON.parse(text) : null;
  }

  // Auth helpers
  async function signUp(email, password, username, name) {
    const res = await fetch(`${SUPABASE_URL}/auth/v1/signup`, {
      method: "POST",
      headers,
      body: JSON.stringify({
        email, password,
        data: { username, name }
      }),
    });
    const data = await res.json();
    if (data.error) throw new Error(data.error.message || data.msg || "Signup failed");
    return data;
  }

  async function signIn(emailOrUsername, password) {
    const input = (emailOrUsername || "").trim();
    // USERNAME sign-in goes through the `username-auth` edge function, which resolves the username
    // with the service role and returns a session. The email never comes back to the client. It
    // used to: the client called the email_for_username RPC with the public anon key, so anyone
    // signed out could turn a public username into that person's real email address and harvest
    // every user's email by walking the usernames in the feed.
    //
    // The EMAIL branch below is deliberately left exactly as it was. It is the overwhelmingly
    // common path, and keeping it a direct call to Supabase auth means a problem with the new
    // username path can never lock anybody out — the worst case is "sign in with your email".
    if (!input.includes("@")) {
      let res;
      try {
        res = await fetch(`${SUPABASE_URL}/functions/v1/username-auth`, {
          method: "POST",
          headers: { "apikey": SUPABASE_KEY, "Authorization": `Bearer ${SUPABASE_KEY}`, "Content-Type": "application/json" },
          body: JSON.stringify({ action: "signin", username: input, password }),
        });
      } catch (e) {
        // Same transport flag the email path sets, so the UI can tell "offline" from "wrong password".
        if (e) e.transportFailure = true;
        throw e;
      }
      const data = await res.json().catch(() => ({}));
      if (res.ok && data.access_token) return data;
      if (res.status === 429) throw new Error(data.message || "Too many attempts. Please try again shortly.");
      if (data.error === "invalid_credentials") throw new Error("Incorrect username or password.");
      // Anything else is our problem, not theirs — send them to the path that always works instead
      // of leaving them staring at a dead login.
      throw new Error("Couldn't sign in with a username just now. Please use your email address.");
    }
    const email = input;
    let res;
    try {
      res = await fetch(`${SUPABASE_URL}/auth/v1/token?grant_type=password`, {
        method: "POST",
        headers,
        body: JSON.stringify({ email, password }),
      });
    } catch (e) {
      // The request never reached the server (offline / DNS / native transport error). Flag it so
      // the sign-in screen can tell a network problem apart from a wrong password.
      if (e) e.transportFailure = true;
      throw e;
    }
    const data = await res.json().catch(() => ({}));
    // Supabase returns auth errors in several shapes (error_description / error / msg / error_code)
    // and a non-2xx status. Catch all of them, and require an access_token, so a failed login
    // surfaces as a clear error instead of falling through to a hung "setting up" screen.
    if (!res.ok || data.error || data.error_description || data.msg || !data.access_token) {
      const raw = data.error_description || data.msg || data.error || "";
      const friendly = /invalid login credentials/i.test(raw)
        ? "Incorrect email or password."
        : (raw || "Sign in failed. Please try again.");
      throw new Error(friendly);
    }
    return data; // { access_token, refresh_token, user }
  }

  async function signOut(token) {
    await fetch(`${SUPABASE_URL}/auth/v1/logout`, {
      method: "POST",
      headers: authHeaders(token),
    });
  }

  async function refreshToken(refresh_token) {
    const res = await fetch(`${SUPABASE_URL}/auth/v1/token?grant_type=refresh_token`, {
      method: "POST",
      headers,
      body: JSON.stringify({ refresh_token }),
    });
    const data = await res.json();
    if (data.error) throw new Error(data.error_description || "Session expired");
    return data;
  }

  // OAuth: start the flow by redirecting to Supabase's authorize endpoint
  function signInWithOAuth(provider) {
    const redirectTo = encodeURIComponent(window.location.origin + window.location.pathname);
    const url = `${SUPABASE_URL}/auth/v1/authorize?provider=${provider}&redirect_to=${redirectTo}`;
    window.location.href = url;
  }

  // Sign in with Apple. On the native iOS build we use the Capacitor Sign in with Apple plugin —
  // the system sheet Apple's App Store guideline 4.8 requires when any social login ships — and
  // exchange the returned identity token with Supabase (grant_type=id_token). Reached through the
  // runtime Capacitor global (same pattern as Haptics/Health/LiveActivity) so there's no build-time
  // import and the web bundle stays clean. On web/PWA there's no native sheet, so we fall back to
  // the hosted OAuth redirect flow, which AppInner's init() completes by parsing #access_token on
  // return. NOTE: the native id_token path can only be exercised on a real device once Ashley adds
  // the "Sign in with Apple" capability + the plugin pod in Xcode — verify it there before submit.
  async function signInWithApple() {
    const Cap = (typeof window !== "undefined") ? window.Capacitor : null;
    const Plugin = Cap?.isNativePlatform?.() ? Cap.Plugins?.SignInWithApple : null;
    if (Plugin?.authorize) {
      // A nonce ties this request to the device session; Apple embeds it in the signed token so
      // Supabase can reject a replayed token. Pass the same raw value to Supabase for verification.
      const nonce = (typeof crypto !== "undefined" && crypto.randomUUID ? crypto.randomUUID() : String(Math.random())).replace(/-/g, "");
      const result = await Plugin.authorize({ scopes: "name email", nonce });
      const idToken = result?.response?.identityToken;
      if (!idToken) throw new Error("Apple sign-in was cancelled.");
      const res = await fetch(`${SUPABASE_URL}/auth/v1/token?grant_type=id_token`, {
        method: "POST",
        headers,
        body: JSON.stringify({ provider: "apple", id_token: idToken, nonce }),
      });
      const data = await res.json().catch(() => ({}));
      if (!res.ok || !data.access_token) {
        throw new Error(data.error_description || data.msg || data.error || "Apple sign-in failed.");
      }
      return data; // { access_token, refresh_token, user } — caller saves the session
    }
    // Web fallback: hosted redirect flow (no session returned here; init() picks it up on return).
    signInWithOAuth("apple");
    return null;
  }

  // ── UNIVERSAL WRITE-RETRY QUEUE ───────────────────────────────────────────
  // Wraps a server write so that if it fails due to being OFFLINE (network error), the write is
  // saved to a durable queue and replayed on reconnect — instead of being silently lost. Only
  // idempotent "set" writes (PATCH / DELETE) are queued: replaying them is safe (last-write-wins),
  // whereas replaying a POST could double-insert. Validation/auth errors (4xx) are NOT queued — the
  // write is bad and would retry forever — they reject so the caller can handle them.
  const WRITE_QUEUE_KEY = "seshd_write_queue";
  const WRITE_QUEUE_CAP = 200; // small idempotent PATCH/DELETE bodies; 200 is ample headroom
  const readQueue = () => { try { return JSON.parse(localStorage.getItem(WRITE_QUEUE_KEY) || "[]"); } catch { return []; } };
  const writeQueue = (q) => {
    try {
      if (q.length > WRITE_QUEUE_CAP) devWarn(`writeQueue: dropping ${q.length - WRITE_QUEUE_CAP} oldest unsynced write(s) over cap ${WRITE_QUEUE_CAP}`);
      localStorage.setItem(WRITE_QUEUE_KEY, JSON.stringify(q.slice(-WRITE_QUEUE_CAP)));
    } catch {}
  };

  // A request that never reached the server (offline / DNS / CORS / timeout) is flagged
  // `transportFailure` by query(); a 4xx/5xx that the server DID answer carries `httpStatus`.
  // We treat only transport failures as "retryable offline" — NOT sniffing e.name, which breaks
  // under CapacitorHttp (native transport errors reject as a generic Error, not a TypeError).
  const isTransportFailure = (e) =>
    (typeof navigator !== "undefined" && navigator.onLine === false) || !!(e && e.transportFailure);
  async function queueWrite(path, opts = {}, token = null) {
    const method = (opts.method || "GET").toUpperCase();
    const retryable = method === "PATCH" || method === "DELETE" || method === "PUT";
    try {
      return await query(path, opts, token);
    } catch (e) {
      const offline = isTransportFailure(e);
      if (offline && retryable) {
        const q = readQueue();
        // Same row (path) + PATCH: merge the partial bodies so changing two settings offline (e.g.
        // theme AND unit) doesn't lose one — both fields end up in a single queued PATCH. For
        // DELETE/PUT, last-write-wins replacement is correct.
        const existingIdx = q.findIndex(item => item.path === path && item.method === method);
        if (existingIdx >= 0 && method === "PATCH") {
          try {
            const merged = { ...JSON.parse(q[existingIdx].body || "{}"), ...JSON.parse(opts.body || "{}") };
            q[existingIdx] = { ...q[existingIdx], body: JSON.stringify(merged), ts: Date.now() };
            writeQueue(q);
            return null;
          } catch { /* fall through to replace if bodies aren't JSON */ }
        }
        const filtered = q.filter(item => !(item.path === path && item.method === method));
        filtered.push({ path, method, body: opts.body || null, headers_extra: opts.headers_extra || null, ts: Date.now() });
        writeQueue(filtered);
        return null; // resolve gracefully — the optimistic local update already happened
      }
      throw e; // real error (validation/auth) — let the caller deal with it
    }
  }

  // Replay queued writes in order. Called on reconnect. Stops on the first hard failure so order is
  // preserved; offline failures re-queue. Token is resolved fresh by the caller.
  async function flushWriteQueue(token) {
    let q = readQueue();
    if (!q.length || !token) return { flushed: 0, remaining: q.length };
    let flushed = 0;
    const remaining = [];
    for (const item of q) {
      try {
        await query(item.path, { method: item.method, body: item.body, headers_extra: item.headers_extra }, token);
        flushed++;
      } catch (e) {
        if (isTransportFailure(e)) { remaining.push(item); } // still offline — keep for next time
        // else: hard error the server answered (validation/auth) — drop it (a doomed write
        // shouldn't block the queue forever)
      }
    }
    writeQueue(remaining);
    return { flushed, remaining: remaining.length };
  }

  const queuedCount = () => readQueue().length;

  // Password reset step 1: email a recovery link. Accepts a username too (same profiles-table
  // lookup as signIn). The link redirects back to the app, which lands with #type=recovery in
  // the hash — handled at boot alongside the OAuth callback.
  async function recover(emailOrUsername) {
    const email = (emailOrUsername || "").trim();
    const redirectTo = (typeof window !== "undefined" && /^https?:/.test(window.location?.origin || ""))
      ? window.location.origin : "https://spotr-drab.vercel.app";
    // A username reset also goes through the edge function, for the same reason as sign-in: the
    // address is resolved server-side and never returned. The function always answers ok whether
    // or not the account exists, which matches the UI's "if an account exists" copy.
    if (!email.includes("@")) {
      await fetch(`${SUPABASE_URL}/functions/v1/username-auth`, {
        method: "POST",
        headers: { "apikey": SUPABASE_KEY, "Authorization": `Bearer ${SUPABASE_KEY}`, "Content-Type": "application/json" },
        body: JSON.stringify({ action: "recover", username: email, redirectTo }),
      }).catch(() => {});
      return;
    }
    await fetch(`${SUPABASE_URL}/auth/v1/recover?redirect_to=${encodeURIComponent(redirectTo)}`, {
      method: "POST", headers, body: JSON.stringify({ email }),
    });
  }
  // Password reset step 2: set the new password using the recovery session's access token.
  async function updatePassword(token, password) {
    const res = await fetch(`${SUPABASE_URL}/auth/v1/user`, {
      method: "PUT",
      headers: { "apikey": SUPABASE_KEY, "Authorization": `Bearer ${token}`, "Content-Type": "application/json" },
      body: JSON.stringify({ password }),
    });
    const data = await res.json().catch(() => ({}));
    if (!res.ok || data.error || data.error_description) {
      throw new Error(data.error_description || data.msg || data.error || "Couldn't update password.");
    }
    return data;
  }

  return { query, rpc, queueWrite, flushWriteQueue, queuedCount, signUp, signIn, signOut, refreshToken, signInWithOAuth, signInWithApple, recover, updatePassword };
})();

// Upload image to Supabase Storage, return public URL
// Upload image via Edge Function proxy — bypasses iOS Safari CORS/Storage issues
// Downscale + recompress an image (base64 data URL) before upload. Phone photos are often
// 3-8MB; this caps the longest side at maxDim and re-encodes as JPEG, typically cutting size
// by 80-95%. Faster uploads on mobile data, smaller storage, snappier loads. Falls back to the
// original on any failure (e.g. canvas blocked) so upload still works.
function compressImage(base64DataUrl, maxDim = 1200, quality = 0.8) {
  return new Promise((resolve) => {
    try {
      const img = new Image();
      img.onload = () => {
        try {
          let { width, height } = img;
          if (width > maxDim || height > maxDim) {
            if (width >= height) { height = Math.round(height * (maxDim / width)); width = maxDim; }
            else { width = Math.round(width * (maxDim / height)); height = maxDim; }
          }
          const canvas = document.createElement("canvas");
          canvas.width = width; canvas.height = height;
          const ctx = canvas.getContext("2d");
          if (!ctx) { resolve(base64DataUrl); return; }
          ctx.drawImage(img, 0, 0, width, height);
          // JPEG drops transparency (fine for photos/avatars) and compresses well.
          const out = canvas.toDataURL("image/jpeg", quality);
          resolve(out && out.length > 20 ? out : base64DataUrl);
        } catch (err) { devWarn("compressImage: canvas/encode failed, using original", err); resolve(base64DataUrl); }
      };
      img.onerror = (err) => { devWarn("compressImage: image failed to load (CORS/format?), using original", err); resolve(base64DataUrl); };
      img.src = base64DataUrl;
    } catch (err) { devWarn("compressImage: unexpected failure, using original", err); resolve(base64DataUrl); }
  });
}

// Upload an image (base64 data URL) directly to Supabase Storage and return its public URL.
// Direct-to-Storage means NO Edge Function is required — just a public "images" bucket.
// Falls back to returning null on failure (callers keep the local preview / handle gracefully).
async function uploadImage(base64DataUrl, token, userId) {
  if (!base64DataUrl || !token) return null;
  try {
    // Compress/resize first (no-op fallback to original if it fails). Always JPEG after this.
    const compressed = await compressImage(base64DataUrl);
    const mime = compressed.match(/data:(.*?);/)?.[1] || "image/jpeg";
    const ext = mime.split("/")[1]?.split("+")[0] || "jpg";
    // base64 → binary blob
    const base64 = compressed.split(",")[1] || "";
    const binary = atob(base64);
    const bytes = new Uint8Array(binary.length);
    for (let i = 0; i < binary.length; i++) bytes[i] = binary.charCodeAt(i);
    // A File (not a bare Blob) so CapacitorHttp's native bridge treats the body as a binary
    // upload and base64-encodes it — a plain Blob falls through its type check and is sent as
    // broken JSON. A File is also a valid fetch body on web, so this works in both paths.
    const blob = new File([bytes], `upload.${ext}`, { type: mime });
    // Unique path per user so uploads don't collide and RLS can scope by the user's folder.
    const path = `${userId || "anon"}/${Date.now()}-${Math.random().toString(36).slice(2, 8)}.${ext}`;
    const res = await fetch(`${SUPABASE_URL}/storage/v1/object/images/${path}`, {
      method: "POST",
      headers: {
        "Authorization": `Bearer ${token}`,
        "Content-Type": mime,
        "x-upsert": "true",
      },
      body: blob,
    });
    if (!res.ok) {
      const err = await res.text().catch(() => "");
      devWarn("uploadImage storage error:", res.status, err);
      return null;
    }
    // Public URL for the object (bucket must be public-read).
    return `${SUPABASE_URL}/storage/v1/object/public/images/${path}`;
  } catch (e) {
    devWarn("uploadImage failed:", e);
    return null;
  }
}

// Group photos are private: they upload to the non-public `group-images` bucket under a
// per-group folder. A storage RLS policy only lets group members write there, so the returned
// value is the storage PATH (not a public URL) — there is no public URL for a private object.
// Viewing goes through signGroupImage() below, which mints a short-lived signed URL that the
// same membership policy gates. Net effect: only members can upload or view a group's photos.
export async function uploadGroupImage(base64DataUrl, token, groupId) {
  if (!base64DataUrl || !token || !groupId) return null;
  try {
    const compressed = await compressImage(base64DataUrl);
    const mime = compressed.match(/data:(.*?);/)?.[1] || "image/jpeg";
    const ext = mime.split("/")[1]?.split("+")[0] || "jpg";
    const base64 = compressed.split(",")[1] || "";
    const binary = atob(base64);
    const bytes = new Uint8Array(binary.length);
    for (let i = 0; i < binary.length; i++) bytes[i] = binary.charCodeAt(i);
    // A File (not a bare Blob) so CapacitorHttp's native bridge treats the body as a binary
    // upload and base64-encodes it — a plain Blob falls through its type check and is sent as
    // broken JSON. A File is also a valid fetch body on web, so this works in both paths.
    const blob = new File([bytes], `upload.${ext}`, { type: mime });
    // Folder = group id so the RLS policy can scope writes/reads to that group's members.
    const path = `${groupId}/${Date.now()}-${Math.random().toString(36).slice(2, 8)}.${ext}`;
    const res = await fetch(`${SUPABASE_URL}/storage/v1/object/group-images/${path}`, {
      method: "POST",
      headers: { "Authorization": `Bearer ${token}`, "Content-Type": mime, "x-upsert": "true" },
      body: blob,
    });
    if (!res.ok) {
      const err = await res.text().catch(() => "");
      devWarn("uploadGroupImage storage error:", res.status, err);
      return null;
    }
    return path; // store the private path in group_posts.image_url
  } catch (e) {
    devWarn("uploadGroupImage failed:", e);
    return null;
  }
}

// Mint a short-lived signed URL for a private group image. The storage RLS SELECT policy only
// lets members sign, so a non-member's request 403s and returns null (image just doesn't render).
export async function signGroupImage(path, token) {
  if (!path || !token) return null;
  try {
    const res = await fetch(`${SUPABASE_URL}/storage/v1/object/sign/group-images/${path}`, {
      method: "POST",
      headers: { "apikey": SUPABASE_KEY, "Authorization": `Bearer ${token}`, "Content-Type": "application/json" },
      body: JSON.stringify({ expiresIn: 3600 }),
    });
    if (!res.ok) return null;
    const data = await res.json().catch(() => null);
    const signed = data?.signedURL || data?.signedUrl;
    return signed ? `${SUPABASE_URL}/storage/v1${signed}` : null;
  } catch {
    return null;
  }
}

// DELETING A POST DELETES ITS PHOTO. Nothing in this file issued a storage DELETE until now — a
// removed post's image sat in the bucket forever, public or private. Both are best-effort: the
// Postgres row is the source of truth for "does this post exist", so a failed cleanup here leaves
// an orphaned object rather than blocking or reverting the deletion the user actually asked for.
async function deletePublicImage(imageUrl, token) {
  if (!imageUrl || !token) return;
  const marker = "/storage/v1/object/public/images/";
  const i = imageUrl.indexOf(marker);
  if (i === -1) return; // not one of ours (external/legacy URL) — nothing to clean up
  const path = imageUrl.slice(i + marker.length);
  try {
    await fetch(`${SUPABASE_URL}/storage/v1/object/images/${path}`, {
      method: "DELETE",
      headers: { "apikey": SUPABASE_KEY, "Authorization": `Bearer ${token}` },
    });
  } catch (e) { devWarn("deletePublicImage failed:", e); }
}
export async function deleteGroupImage(path, token) {
  if (!path || !token) return;
  try {
    await fetch(`${SUPABASE_URL}/storage/v1/object/group-images/${path}`, {
      method: "DELETE",
      headers: { "apikey": SUPABASE_KEY, "Authorization": `Bearer ${token}` },
    });
  } catch (e) { devWarn("deleteGroupImage failed:", e); }
}


// Session storage
const SESSION_STORAGE_KEY = "seshd_session";
// ── Session tokens: iOS Keychain on native, localStorage on web ─────────────────
// On a native build with capacitor-secure-storage-plugin synced, the Supabase
// access/refresh tokens live ONLY in the hardware-encrypted Keychain — never in
// localStorage or the Preferences (UserDefaults) mirror, both of which are
// unencrypted at rest. Reads stay synchronous for the ~30 call sites via a module
// cache that boot hydration populates from the Keychain BEFORE React mounts (see
// hydrateSessionFromKeychain). Web builds and native builds that haven't run
// `npx cap sync ios` yet keep the localStorage path unchanged.
function secureStore() {
  const Cap = (typeof window !== "undefined") ? window.Capacitor : null;
  if (Cap?.isNativePlatform?.() && Cap.Plugins?.SecureStoragePlugin) return Cap.Plugins.SecureStoragePlugin;
  return null;
}
let _sessionCache; // undefined = not hydrated; null = known signed-out; object = session
function loadSession() {
  if (_sessionCache !== undefined) return _sessionCache;
  try { return JSON.parse(localStorage.getItem(SESSION_STORAGE_KEY)); } catch { return null; }
}
// Boot/session diagnostics — surfaced as a tiny line on the auth screen so a device where
// session persistence fails can tell us exactly which step went wrong (Keychain hit/miss/error,
// save confirmed/failed). Keys start with seshd_ so the Preferences mirror carries them too.
function setBootDiag(s) { try { localStorage.setItem("seshd_boot_diag", String(s).slice(0, 80)); } catch {} }
function setSaveDiag(s) { try { localStorage.setItem("seshd_kc_save", String(s).slice(0, 60)); } catch {} }
// PARANOIA RULE for everything below: never destroy a copy of the session until its
// replacement write is CONFIRMED. A silently-failing Keychain plugin must degrade to
// "session kept in localStorage/Preferences" (still app-sandboxed), never to "signed out".
function saveSession(s) {
  const sec = secureStore();
  const payload = JSON.stringify(s);
  if (sec) {
    _sessionCache = s;
    try {
      sec.set({ key: SESSION_STORAGE_KEY, value: payload }).then(() => {
        setSaveDiag("kc-save:ok");
        // Keychain write CONFIRMED — now it's safe to scrub the unencrypted copies
        // (explicitly on both stores, so this holds even if the mirror isn't installed).
        try { localStorage.removeItem(SESSION_STORAGE_KEY); } catch {}
        try { nativePrefs()?.remove({ key: SESSION_STORAGE_KEY }).catch(() => {}); } catch {}
      }).catch((e) => {
        setSaveDiag("kc-save:err " + String((e && e.message) || e || "?").slice(0, 32));
        try { localStorage.setItem(SESSION_STORAGE_KEY, payload); } catch {}
      });
    } catch (e) {
      setSaveDiag("kc-save:threw");
      try { localStorage.setItem(SESSION_STORAGE_KEY, payload); } catch {}
    }
  } else {
    try { localStorage.setItem(SESSION_STORAGE_KEY, payload); } catch {}
  }
}
function clearSession() {
  _sessionCache = secureStore() ? null : undefined;
  try { localStorage.removeItem(SESSION_STORAGE_KEY); } catch {}
  try { secureStore()?.remove({ key: SESSION_STORAGE_KEY }).catch(() => {}); } catch {}
  try { nativePrefs()?.remove({ key: SESSION_STORAGE_KEY }).catch(() => {}); } catch {}
}
// Resolve to undefined (instead of hanging) if a plugin call never settles — a wedged bridge
// must not white-screen the boot forever.
function _withTimeout(p, ms) {
  return Promise.race([p, new Promise(res => setTimeout(() => res(undefined), ms))]);
}
// Boot-time hydration + one-time migration. Runs inside hydrateFromNative() (before React
// mounts), so synchronous loadSession() calls see the Keychain session from the first render.
async function hydrateSessionFromKeychain() {
  const sec = secureStore();
  if (!sec) { setBootDiag("kc:no-plugin"); return; }
  try {
    const res = await _withTimeout(sec.get({ key: SESSION_STORAGE_KEY }), 4000);
    if (res === undefined) {
      // Timed out — Keychain state unknown. Fall back to any localStorage copy but do NOT
      // scrub or migrate anything (we might race a functioning-but-slow plugin).
      setBootDiag("kc:timeout");
      try { _sessionCache = JSON.parse(localStorage.getItem(SESSION_STORAGE_KEY)) || null; } catch { _sessionCache = null; }
      return;
    }
    const value = res && res.value;
    _sessionCache = value ? JSON.parse(value) : null;
    setBootDiag(value ? "kc:hit" : "kc:empty");
    // Keychain is the source of truth now — scrub any old unencrypted copies explicitly.
    try { localStorage.removeItem(SESSION_STORAGE_KEY); } catch {}
    try { await nativePrefs()?.remove({ key: SESSION_STORAGE_KEY }); } catch {}
  } catch (e) {
    // Keychain miss (first run) or a broken plugin. Use the localStorage copy if present —
    // and NEVER null a session we successfully parsed just because the migration write fails.
    let raw = null;
    try { raw = localStorage.getItem(SESSION_STORAGE_KEY); } catch {}
    if (raw) {
      try { _sessionCache = JSON.parse(raw); } catch { _sessionCache = null; raw = null; }
    } else {
      _sessionCache = null;
    }
    setBootDiag("kc:miss(" + String((e && e.message) || e || "?").slice(0, 24) + ") ls:" + (raw ? "hit" : "none"));
    if (raw && _sessionCache) {
      // Best-effort migration into the Keychain; scrub the plaintext copies ONLY on success.
      try {
        await sec.set({ key: SESSION_STORAGE_KEY, value: raw });
        localStorage.removeItem(SESSION_STORAGE_KEY);
        try { await nativePrefs()?.remove({ key: SESSION_STORAGE_KEY }); } catch {}
      } catch { /* keep the localStorage fallback — signed-in beats scrubbed */ }
    }
  }
}

// Run an authed REST query; if it fails (most often an expired access token —
// the documented foreground-refresh race), refresh the session once and retry
// before giving up. Used by screens whose own access_token prop can go stale
// (Messages/Chat poll on intervals), so a dead token doesn't leave them empty.
async function queryWithRetry(path, opts, token) {
  const tok = token || loadSession()?.access_token;
  try {
    return await sb.query(path, opts, tok);
  } catch (e) {
    const saved = loadSession();
    if (!saved?.refresh_token) throw e;
    const fresh = await sb.refreshToken(saved.refresh_token);
    const merged = { ...saved, ...fresh };
    saveSession(merged);
    return await sb.query(path, opts, merged.access_token);
  }
}

