function ReportHost({ C, token, currentUserId }) {
  const [rp, setRp] = useState(null);
  const [busy, setBusy] = useState(false);
  _setReport = setRp;
  useEffect(() => {
    if (!rp) return;
    const onKey = (e) => { if (e.key === "Escape") setRp(null); };
    window.addEventListener("keydown", onKey);
    return () => window.removeEventListener("keydown", onKey);
  }, [rp?.key]);
  const close = () => { if (!busy) setRp(null); };
  const submit = async (reason) => {
    if (busy) return;
    setBusy(true);
    try {
      const res = await fetch(`${SUPABASE_URL}/rest/v1/reports`, {
        method:"POST",
        headers:{ "apikey":SUPABASE_KEY, "Authorization":`Bearer ${token}`, "Content-Type":"application/json" },
        body: JSON.stringify({
          reporter_id: currentUserId,
          reported_user_id: rp.reportedUserId || null,
          content_type: rp.type,
          content_id: rp.id,
          reason,
        }),
      });
      setRp(null);
      // Always thank the user, even on a network error — never hint that a report "failed"
      // (mirrors the app's neutral-confirmation style) and log the error for follow-up.
      if (!res.ok) devWarn("report insert failed:", res.status, await res.text().catch(()=>""));
      toast("Thanks for reporting. Our team will review this within 24 hours.", "success");
    } catch (e) {
      devWarn("report failed:", e);
      setRp(null);
      toast("Thanks for reporting. Our team will review this within 24 hours.", "success");
    } finally { setBusy(false); }
  };
  const accent = C.accent || "#65a30d";
  return (
    <Sheet open={!!rp} onClose={close} z={4000} backdrop="rgba(0,0,0,0.7)"
      panelStyle={{ background:C.surface, borderRadius:"18px 18px 0 0", padding:"20px 18px calc(24px + env(safe-area-inset-bottom))", border:`1px solid ${C.border}`, borderBottom:"none" }}>
      {rp && (
        <>
          <div style={{ fontSize:18, fontWeight:800, color:C.text, marginBottom:4, letterSpacing:-0.3 }}>Report{rp.label ? ` ${rp.label}` : ""}</div>
          <div style={{ fontSize:13, color:C.sub, lineHeight:1.5, marginBottom:16 }}>Why are you reporting this? This is anonymous.</div>
          <div style={{ display:"flex", flexDirection:"column", gap:8 }}>
            {REPORT_REASONS.map(r => (
              <button key={r.id} disabled={busy} onClick={() => submit(r.id)} style={{
                textAlign:"left", background:C.bg, border:`1px solid ${C.border}`, color:C.text,
                borderRadius:11, padding:"13px 15px", fontSize:14, fontWeight:600,
                cursor:busy?"default":"pointer", fontFamily:F, opacity:busy?0.6:1,
              }}>{r.label}</button>
            ))}
          </div>
          <button onClick={close} disabled={busy} style={{ width:"100%", marginTop:12, background:"transparent", border:"none", color:C.sub, borderRadius:11, padding:"12px", fontSize:14, fontWeight:600, cursor:busy?"default":"pointer", fontFamily:F }}>Cancel</button>
        </>
      )}
    </Sheet>
  );
}
function ToastHost() {
  // Seed from the queue: a toast fired before this host mounts (e.g. a failure during the
  // boot "Setting up your account" screen, which early-returns before ToastHost renders)
  // would otherwise sit in _toastQueue forever and never display.
  const [t, setT] = useState(() => _toastQueue[0] || null);
  _setToast = setT;
  useEffect(() => {
    if (!t) return;
    // Give actionable toasts (e.g. "Undo") a longer window to react to.
    const id = setTimeout(() => _dismissToast(), t.action ? 5000 : 2800);
    return () => clearTimeout(id);
  }, [t?.id]);
  if (!t) return null;
  // Liquid glass, matching the bottom nav pill it floats above. It's position:fixed over
  // real app content, so the backdrop blur here is live (unlike an in-flow bar's would be).
  // Success/error keep a strong color tint for at-a-glance meaning; info is neutral glass.
  const glassBg = t.type === "error"
    ? "linear-gradient(165deg, rgba(248,84,84,0.9) 0%, rgba(200,38,38,0.82) 100%)"
    : t.type === "success"
    ? "linear-gradient(165deg, rgba(52,211,111,0.9) 0%, rgba(18,150,70,0.82) 100%)"
    : "linear-gradient(165deg, rgba(70,70,78,0.72) 0%, rgba(34,34,40,0.78) 100%)";
  return (
    <div style={{
      position:"fixed", bottom:90, left:"50%", transform:"translateX(-50%)",
      background:glassBg, color:"#fff", borderRadius:20, padding:"10px 20px",
      backdropFilter:"blur(24px) saturate(1.6)", WebkitBackdropFilter:"blur(24px) saturate(1.6)",
      border:"1px solid rgba(255,255,255,0.22)",
      fontSize:13, fontWeight:600, zIndex:999, whiteSpace:"nowrap",
      boxShadow:"0 10px 30px rgba(0,0,0,0.3), inset 0 1px 1px rgba(255,255,255,0.25)", fontFamily:F,
      animation:"fadeInUp 0.2s ease", display:"flex", alignItems:"center", gap:14
    }}>
      {t.msg}
      {t.action && (
        <button onClick={() => { try { t.action.onAction && t.action.onAction(); } catch (e) {} _dismissToast(); }}
          style={{ background:"rgba(255,255,255,0.18)", border:"none", color:"#fff", borderRadius:12, padding:"5px 12px", fontSize:13, fontWeight:800, cursor:"pointer", fontFamily:F, letterSpacing:0.2 }}>
          {t.action.label}
        </button>
      )}
      <style>{`@keyframes fadeInUp{from{opacity:0;transform:translate(-50%,12px)}to{opacity:1;transform:translate(-50%,0)}}`}</style>
    </div>
  );
}

