// Real Symmetric Strength weight-class standards (no age, 1-rep maxes, lbs), per sex, for the
// 8 main lifts they publish a comparable standard for. Keys are anchor bodyweights (lb); each
// value array is [Untrained, Novice, Intermediate, Proficient, Advanced, Exceptional, Elite,
// World Class]. computeStrengthScore interpolates between anchors by the user's actual
// bodyweight (and linearly extrapolates past the ends using the nearest segment's slope)
// instead of using a single fixed ratio, since the real ratio is NOT constant across bodyweight.
const STRENGTH_WEIGHT_CLASS_LBS = {
  male: {
    "Barbell Back Squat":       { 150:[120,180,240,300,350,395,445,495], 208:[145,220,295,365,425,490,550,610], 250:[155,235,315,390,455,520,585,650] },
    "Front Squat":              { 150:[95,145,190,240,280,320,360,395],  208:[115,175,235,295,340,390,440,490], 250:[125,190,250,315,365,420,470,520] },
    "Deadlift":                 { 150:[135,205,275,345,400,455,515,570], 208:[170,250,335,420,490,560,630,700], 250:[180,270,360,450,525,600,675,750] },
    "Sumo Deadlift":            { 150:[135,205,275,345,400,455,515,570], 208:[170,250,335,420,490,560,630,700], 250:[180,270,360,450,525,600,675,750] },
    "Barbell Bench Press":      { 150:[90,135,180,225,260,295,335,370],  208:[110,165,220,275,320,365,410,455], 250:[115,175,235,295,340,390,440,485] },
    "Incline Bench Press":      { 150:[75,110,145,185,215,245,275,305],  208:[90,135,180,225,260,300,335,375],  250:[95,145,190,240,280,320,360,400] },
    "Overhead Press (Barbell)": { 150:[60,85,115,145,170,195,215,240],   208:[70,105,140,180,205,235,265,295],  250:[75,115,150,190,220,255,285,315] },
    "Barbell Row":              { 150:[75,110,145,180,210,240,270,305],  208:[90,135,180,225,260,295,335,370],  250:[95,145,190,240,280,320,360,395] },
  },
  female: {
    "Barbell Back Squat":       { 100:[65,100,135,165,195,225,250,280],  130:[80,120,165,205,240,270,305,340],  180:[100,155,205,255,295,340,380,425] },
    "Front Squat":              { 100:[55,80,105,135,155,180,200,225],   130:[65,100,130,165,190,220,245,270],  180:[80,120,165,205,240,270,305,340] },
    "Deadlift":                 { 100:[80,120,160,200,230,265,300,330],  130:[95,145,195,245,285,325,365,405],  180:[120,180,245,305,355,405,455,505] },
    "Sumo Deadlift":            { 100:[80,120,160,200,230,265,300,330],  130:[95,145,195,245,285,325,365,405],  180:[120,180,245,305,355,405,455,505] },
    "Barbell Bench Press":      { 100:[45,70,90,115,130,150,170,190],    130:[55,85,110,140,160,185,210,230],   180:[70,105,140,175,200,230,260,290] },
    "Incline Bench Press":      { 100:[35,55,75,95,110,125,140,155],     130:[45,70,90,115,130,150,170,190],    180:[55,85,115,140,165,190,215,235] },
    "Overhead Press (Barbell)": { 100:[30,45,60,75,85,100,110,125],      130:[35,55,70,90,105,120,135,150],     180:[45,65,90,110,130,150,170,185] },
    "Barbell Row":              { 100:[40,65,85,105,125,140,160,175],    130:[50,75,105,130,150,170,195,215],   180:[65,95,130,160,190,215,240,270] },
  },
};
const STRENGTH_WC_LEVEL_KEYS = ["Novice","Intermediate","Proficient","Advanced","Exceptional","Elite","WorldClass"];
// Interpolates (or extrapolates past the table's ends) this lift's level thresholds at a given
// bodyweight for the given sex, then expresses them as bodyweight ratios so the result drops
// into the same ratio-based scoring path as the fixed-table lifts. Returns null if this
// sex/lift has no real weight-class data (caller should fall back to the fixed-ratio table).
function weightClassRatios(sex, lift, bwLbs) {
  const table = (STRENGTH_WEIGHT_CLASS_LBS[sex] || {})[lift];
  if (!table || !bwLbs || bwLbs <= 0) return null;
  const anchors = Object.keys(table).map(Number).sort((a, b) => a - b);
  let lo = anchors[0], hi = anchors[1];
  for (let i = 0; i < anchors.length - 1; i++) {
    if (bwLbs >= anchors[i]) { lo = anchors[i]; hi = anchors[i + 1]; }
  }
  const t = (bwLbs - lo) / (hi - lo);
  const loVals = table[lo], hiVals = table[hi];
  const out = {};
  STRENGTH_WC_LEVEL_KEYS.forEach((key, i) => {
    const idx = i + 1; // index 0 in the arrays is Untrained, which has no standards key
    const abs = loVals[idx] + t * (hiVals[idx] - loVals[idx]);
    out[key] = Math.max(0, abs) / bwLbs;
  });
  return out;
}
// Builds the effective standards object for a sex at this bodyweight: real weight-class ratios
// where available, the fixed-ratio fallback (accessory lifts) otherwise.
function standardsForBw(sex, bwLbs) {
  const base = STRENGTH_STANDARDS_BY_SEX[sex] || STRENGTH_STANDARDS_BY_SEX.male;
  const out = {};
  for (const lift of Object.keys(base)) {
    out[lift] = weightClassRatios(sex, lift, bwLbs) || base[lift];
  }
  return out;
}
const STRENGTH_LIFT_ALIASES = {
  "Barbell Bench Press": ["Bench Press","Flat Barbell Bench","Flat Bench"],
  "Barbell Back Squat": ["Back Squat","Low Bar Squat","High Bar Squat","Squat"],
  "Deadlift": ["Conventional Deadlift","Trap Bar Deadlift","Hex Bar Deadlift"],
  "Sumo Deadlift": ["Sumo Pull","Sumo DL"],
  "Overhead Press (Barbell)": ["Overhead Press","OHP","Standing Barbell OHP","Standing OHP","Standing Press","Strict Press","Military Press","Barbell OHP","Barbell Overhead Press"],
  "Incline Bench Press": ["Incline Barbell Press","Incline Bench","Incline Press"],
  "Front Squat": ["Barbell Front Squat"],
  "Barbell Row": ["Bent-Over Row","Barbell Bent-Over Row","Pendlay Row","Bent Over Barbell Row","BB Row"],
  "Romanian Deadlift": ["RDL","Barbell RDL","Stiff-Leg Deadlift","Stiff Leg Deadlift"],
  "Hip Thrust": ["Barbell Hip Thrust","Glute Bridge","Barbell Glute Bridge"],
};
const STRENGTH_LEVELS = ["Untrained","Novice","Intermediate","Proficient","Advanced","Exceptional","Elite","World Class"];
// Control points (one per STRENGTH_LEVELS index) for the headline 0-100 score. A straight linear
// mapping pins 100 to World Class (literal world-record territory), which makes everyday strong
// lifters score punishingly low. This curve front-loads the range so the levels most people
// actually occupy (Novice..Advanced) are spread across more of 0-100, while Elite/World Class
// still sit at the top — the level LABELS themselves are unaffected, only this display number.
// Tuned to be motivating for the average trained lifter: a solid Intermediate (genuinely above
// the typical gym-goer) lands ~60, Advanced ~84 — not the "45/100 feels like a fail" of before.
// Elite/World Class barely move (97/100), so the top of the scale still means what it says.
const STRENGTH_SCORE_CURVE = [0, 38, 60, 73, 84, 92, 97, 100];
// Converts a raw strength level fraction (levelIdx / 7, as stored in regionFrac) to the
// DISPLAY fraction used for map coloring and the "Lagging" cutoff — through the same curve
// as the headline score, so every strength surface tells one story. Raw lvl/7 painted an
// Intermediate lifter (a solid, above-average gym-goer) at 29% = angry red; through the
// curve they sit at 0.60 = amber-green, matching their 60/100 score. The analytic values
// underneath (imbalance detection) stay raw — only what the user SEES is curved.
function _strengthDisplayFrac(frac) {
  const lvl = Math.max(0, Math.min(STRENGTH_SCORE_CURVE.length - 1, Math.round((frac || 0) * (STRENGTH_LEVELS.length - 1))));
  return STRENGTH_SCORE_CURVE[lvl] / 100;
}

// Movement patterns: lifts that compete for the SAME slot in the score. The strongest
// lift in each pattern represents you — so front + back squat don't both drag the average
// (your best squat counts), and incline vs flat bench pick the better one.
const STRENGTH_PATTERNS = {
  "Squat":    ["Barbell Back Squat", "Front Squat"],
  "Bench":    ["Barbell Bench Press", "Incline Bench Press"],
  "Deadlift": ["Deadlift", "Sumo Deadlift"],
  "Press":    ["Overhead Press (Barbell)"],
  "Row":      ["Barbell Row"],
  "RDL":      ["Romanian Deadlift"],
  "Hinge":    ["Hip Thrust"],
};

// The headline 0-100 score / overall level averages only the user's BEST this-many patterns,
// dropping their weakest few. Lifts you train hard as accessories for reps (often a hinge or
// the press) score low and drag the average on shaky data; counting each person's strongest
// patterns keeps the number representative without singling out specific lifts. All winners
// still appear in `lifts` (per-lift list + body map) regardless of whether they're counted.
const STRENGTH_SCORE_TOP_N = 5;

// Lifts evaluated for the muscle-balance body map ONLY — they get a level so their region can
// be shaded, but are deliberately excluded from STRENGTH_PATTERNS so they never count toward
// the strength score (no real per-bodyweight standard exists, so scoring them would dilute it).
const STRENGTH_MAP_ONLY_LIFTS = ["Standing Calf Raise"];

// Age multiplier on strength standards. Strength peaks ~20-30; after 35 it declines ~1%/yr,
// accelerating past 50. Below 18, standards are slightly lower too. The thresholds are
// MULTIPLIED by this factor (≤1 outside the prime years), so an older or younger lifter
// reaches each level at a proportionally lower ratio — age-fair scoring rather than
// comparing a 55-year-old to a 25-year-old's numbers.
function ageStrengthFactor(age) {
  if (!age || age < 1) return 1;
  if (age < 18) return 0.92 + (age - 14) * 0.02;        // 14→0.92 .. 18→1.0
  if (age <= 30) return 1;                               // prime
  if (age <= 35) return 1 - (age - 30) * 0.005;          // gentle
  if (age <= 50) return 0.975 - (age - 35) * 0.01;       // ~1%/yr
  return Math.max(0.6, 0.825 - (age - 50) * 0.014);      // steeper past 50
}

function levelForRatio(standards, lift, ratio, ageFactor = 1) {
  const s = standards[lift];
  if (!s) return "Untrained";
  const f = ageFactor || 1;
  if (ratio >= s.WorldClass * f) return "World Class";
  if (ratio >= s.Elite * f) return "Elite";
  if (ratio >= s.Exceptional * f) return "Exceptional";
  if (ratio >= s.Advanced * f) return "Advanced";
  if (ratio >= s.Proficient * f) return "Proficient";
  if (ratio >= s.Intermediate * f) return "Intermediate";
  if (ratio >= s.Novice * f) return "Novice";
  return "Untrained";
}

// sex: "male" | "female" | "other". Standards are physiological, so "other" uses the midpoint
// of the male/female thresholds (a neutral baseline) rather than forcing a binary choice.
// Returns { overall, score (0-100), lifts:[{lift, best, ratio, level}], bodyweight, sex } or
// { ready:false } if there isn't enough data (no bodyweight or no main-lift PRs).
// The strength-score curve on your profile: replay the score as it stood at a series of past
// cutoffs. Raw current-PR fallbacks are excluded so an old snapshot cannot see future bests,
// and `asOf` makes the stale-lift decay relative to each snapshot rather than to today.
// Module level and exported because it was inline in ProfileScreen, where the only way to
// check it was to look at the chart and squint.
function strengthScoreHistory(store, unit, sex, now) {

    const hist = store.history || {};
    const dates = Object.keys(hist).sort();
    if (dates.length < 2) return null;
    const firstMs = new Date(dates[0] + "T12:00:00").getTime();
    // Adaptive granularity. The threshold used to be 12 weeks, which is far too early: at 84
    // days a monthly chart has only THREE month-ends to draw, so an account that had just
    // crossed the line went from a dozen weekly points to a nearly empty chart. Monthly only
    // earns its place once there are enough months to make a curve — about eight.
    const spanDays = (now.getTime() - firstMs) / 864e5;
    const weekly = spanDays < 240;
    const snapshots = [];
    if (weekly) {
      const nWeeks = Math.min(11, Math.floor(spanDays / 7));
      for (let i = nWeeks; i >= 1; i--) snapshots.push(new Date(now.getTime() - i * 7 * 864e5));
    } else {
      for (let i = 11; i >= 1; i--) {
        const mEnd = new Date(now.getFullYear(), now.getMonth() - i + 1, 0); // last day of that month
        if (mEnd.getTime() >= firstMs) snapshots.push(mEnd);
      }
    }
    snapshots.push(now);
    const MONTHS = ["Jan","Feb","Mar","Apr","May","Jun","Jul","Aug","Sep","Oct","Nov","Dec"];
    const pts = snapshots.map((d, i) => {
      const cutoff = dateKeyOf(d);
      const histCut = {};
      for (const k of dates) { if (k <= cutoff) histCut[k] = hist[k]; }
      if (!Object.keys(histCut).length) return null;
      // THE STRENGTH SCORE IS BODYWEIGHT-RELATIVE, so a snapshot needs a weight — but dropping
      // every snapshot before your FIRST weigh-in threw away real training history. Measured on
      // live data: first workout 10 May, first body-log entry 4 June, so the 31 May snapshot was
      // discarded and a three-month-old account with 58 workouts drew THREE points. Bodyweight
      // moves slowly; the earliest weight on record is a far better stand-in than nothing.
      let bodyLog = (store.bodyLog || []).filter(bp => (bp.date || "") <= cutoff);
      if (!bodyLog.length) {
        const earliest = [...(store.bodyLog || [])].sort((a, b) => String(a.date).localeCompare(String(b.date)))[0];
        if (!earliest) return null;
        bodyLog = [{ ...earliest, date: cutoff }];
      }
      const snap = computeStrengthScore(
        { ...store, history: histCut, bodyLog, prs: {}, prEvents: (store.prEvents || []).filter(e => (e.date || "") <= cutoff) },
        unit, sex, d.getTime()
      );
      if (!snap.ready) return null;
      return { value: snap.score, date: cutoff, label: i === snapshots.length - 1 ? "Now" : (weekly ? `${d.getMonth()+1}/${d.getDate()}` : MONTHS[d.getMonth()]) };
    }).filter(Boolean);
    return pts.length >= 2 ? pts : null;
}

function computeStrengthScore(store, unit, sex = "male", asOf = null) {
  const nowMs = asOf || Date.now();
  const bodyLog = [...(store.bodyLog || [])].sort((a, b) => (b.date || "").localeCompare(a.date || ""));
  const bw = bodyLog.length ? parseFloat(bodyLog[0].weight) : null;
  if (!bw || bw <= 0) return { ready: false, reason: "no_bodyweight" };
  // Bodyweight drives every ratio below — flag when it's stale so a months-old weigh-in
  // doesn't silently masquerade as today's number.
  const bwDate = bodyLog[0].date;
  const bodyweightAgeDays = bwDate ? Math.round((nowMs - new Date(bwDate + "T12:00:00").getTime()) / 864e5) : null;
  // The weight-class table is in lbs, so the real-data interpolation needs bodyweight in lbs
  // regardless of the user's display unit.
  const bwLbs = unit === "kg" ? bw * LBS_PER_KG : bw;
  let standards;
  if (sex === "other") {
    // Average the male & female bodyweight-aware thresholds for a neutral baseline.
    const m = standardsForBw("male", bwLbs), f = standardsForBw("female", bwLbs);
    standards = {};
    for (const lift of Object.keys(m)) {
      standards[lift] = {};
      for (const lvl of Object.keys(m[lift])) {
        standards[lift][lvl] = (m[lift][lvl] + f[lift][lvl]) / 2;
      }
    }
  } else {
    standards = standardsForBw(sex, bwLbs);
  }
  const prs = store.prs || {};
  // Normalize for tolerant matching — strips parentheticals like "(heavy)", punctuation, casing.
  const norm = (s) => (s || "").toLowerCase().replace(/\([^)]*\)/g, "").replace(/[^a-z0-9]+/g, " ").trim();
  // Keyword signatures so a PR logged under almost any sensible name still maps to a scored lift.
  // Exclusions prevent double-counting (e.g. incline bench must not also count as flat bench).
  const LIFT_KEYWORDS = {
    "Barbell Bench Press": (n) => n.includes("bench") && !n.includes("incline") && !n.includes("decline") && !n.includes("close grip") && !n.includes("db") && !n.includes("dumbbell") && !n.includes("smith") && !n.includes("machine") && !n.includes("floor"),
    "Barbell Back Squat": (n) => n.includes("squat") && !n.includes("front") && !n.includes("hack") && !n.includes("goblet") && !n.includes("split") && !n.includes("sissy") && !n.includes("bulgarian") && !n.includes("smith") && !n.includes("machine") && !n.includes("belt") && !n.includes("pendulum"),
    "Deadlift": (n) => n.includes("deadlift") && !n.includes("romanian") && !n.includes("rdl") && !n.includes("stiff") && !n.includes("single") && !n.includes("sumo"),
    "Sumo Deadlift": (n) => n.includes("sumo") && n.includes("deadlift"),
    "Overhead Press (Barbell)": (n) => (n.includes("overhead press") || n.includes("ohp") || n.includes("military") || (n.includes("strict press")) || (n.includes("shoulder press") && n.includes("barbell"))) && !n.includes("db") && !n.includes("dumbbell") && !n.includes("machine"),
    "Incline Bench Press": (n) => n.includes("incline") && (n.includes("bench") || n.includes("press")) && !n.includes("db") && !n.includes("dumbbell") && !n.includes("machine") && !n.includes("smith"),
    "Front Squat": (n) => n.includes("front squat"),
    "Barbell Row": (n) => (n.includes("barbell row") || n.includes("bent over row") || n.includes("bent-over row") || n.includes("pendlay") || (n.includes("bb row"))) && !n.includes("db") && !n.includes("dumbbell") && !n.includes("cable") && !n.includes("machine") && !n.includes("seated"),
    "Romanian Deadlift": (n) => n.includes("romanian") || n.includes("rdl") || n.includes("stiff leg") || n.includes("stiff-leg"),
    "Hip Thrust": (n) => n.includes("hip thrust") || n.includes("glute bridge"),
    // Standing/smith calf raises only — seated and leg-press variants load very differently.
    // Map-only (see STRENGTH_MAP_ONLY_LIFTS): shades the calves region, not part of the score.
    "Standing Calf Raise": (n) => n.includes("calf") && (n.includes("raise") || n.includes("press")) && !n.includes("seated") && !n.includes("leg press") && !n.includes("single") && !n.includes("donkey"),
  };
  // Strength standards are defined against a 1-REP MAX. store.prs holds the heaviest raw weight
  // lifted (any rep count), which understates strength for higher-rep PRs. So we estimate 1RM
  // from the best set in history per lift (Epley via calc1RM), which is the correct comparison.
  const histUnit = unit;
  const liftBestE1RM = {}; // canonical lift -> best estimated 1RM (in display unit)
  const scanMatch = (name) => {
    for (const canonical of Object.keys(standards)) {
      const kw = LIFT_KEYWORDS[canonical];
      const aliasNames = [canonical, ...(STRENGTH_LIFT_ALIASES[canonical] || [])];
      if (aliasNames.includes(name) || (kw && kw(norm(name)))) return canonical;
    }
    return null;
  };
  for (const d of Object.keys(store.history || {})) {
    for (const sess of Object.values(store.history[d] || {})) {
      const sUnit = sess.unit || histUnit;
      for (const ex of (sess.exercises || [])) {
        if (!ex.name) continue;
        const canonical = scanMatch(ex.name);
        if (!canonical) continue;
        for (const s of (ex.sets || [])) {
          if (s.type === "warmup") continue;
          const done = s.done === true || (s.done === undefined && parseFloat(s.reps || s.r) > 0);
          if (!done) continue;
          const w = parseFloat(s.weight ?? s.w);
          const r = parseInt(s.reps ?? s.r);
          if (!w || !r || r < 1) continue;
          // Epley is unreliable past ~10 reps (a 20-rep set wildly inflates e1RM), so cap
          // the rep input — high-rep sets still count, just conservatively.
          const e1rmRaw = calc1RM(w, Math.min(r, 10));
          if (!e1rmRaw) continue;
          // Normalize to the display unit used for bodyweight comparison.
          let e1rm = sUnit === unit ? e1rmRaw : cvt(e1rmRaw, sUnit, unit);
          // A max from 8 months ago overstates current strength after a layoff — decay
          // bests older than 4 months by ~1.2%/month, floored at 85%.
          const ageDays = (nowMs - new Date(d + "T12:00:00").getTime()) / 864e5;
          if (ageDays > 120) e1rm *= Math.max(0.85, 1 - (ageDays - 120) * 0.0004);
          if (!liftBestE1RM[canonical] || e1rm > liftBestE1RM[canonical]) liftBestE1RM[canonical] = e1rm;
        }
      }
    }
  }
  // Fallback: if history has no matching sets but a stored PR exists, use the raw PR (better than
  // nothing — treats it as a 1RM, slightly conservative for high-rep PRs). Unlike the e1RM-from-
  // history path above, store.prs has no date on its own — so look up the matching prEvents entry
  // (logged at the moment the PR was hit) to find when it happened and apply the same staleness
  // decay, instead of letting an old PR silently overstate current strength forever.
  const prEvents = store.prEvents || [];
  const prDate = (name, weightLbs) => {
    let best = null;
    for (const e of prEvents) {
      if (e.name === name && Math.abs((e.weightLbs || 0) - weightLbs) < 0.6) {
        if (!best || e.date > best) best = e.date;
      }
    }
    return best;
  };
  const bestPR = (canonical) => {
    if (liftBestE1RM[canonical]) return liftBestE1RM[canonical];
    const names = [canonical, ...(STRENGTH_LIFT_ALIASES[canonical] || [])];
    const exactPairs = names.map(n => [n, prs[n]]).filter(([, v]) => v != null && v > 0);
    const kw = LIFT_KEYWORDS[canonical];
    const fuzzyPairs = kw ? Object.entries(prs).filter(([name, v]) => v != null && v > 0 && kw(norm(name))) : [];
    const all = [...exactPairs, ...fuzzyPairs].map(([name, lbs]) => {
      const date = prDate(name, lbs);
      let val = lbs;
      if (date) {
        const ageDays = (nowMs - new Date(date + "T12:00:00").getTime()) / 864e5;
        if (ageDays > 120) val *= Math.max(0.85, 1 - (ageDays - 120) * 0.0004);
      }
      // prs are stored in lbs; convert to display unit if needed.
      return unit === "lbs" ? val : cvt(val, "lbs", unit);
    });
    return all.length ? Math.max(...all) : null;
  };
  // Age-fair scaling: scale standards by the user's age (if known).
  const age = (() => {
    const a = parseInt(store.age || store.profileAge);
    if (a > 0 && a < 100) return a;
    if (store.birthYear) { const y = new Date().getFullYear() - parseInt(store.birthYear); if (y > 0 && y < 100) return y; }
    return null;
  })();
  const ageFactor = ageStrengthFactor(age);
  // Score each MOVEMENT PATTERN by its best-performing lift, so logging a light variant
  // (e.g. a few easy front squats) never drags down a strong main lift.
  const lifts = [];
  const scoredWinners = []; // {lvlIdx, score} for every pattern with data — top N drive the score
  const usedLifts = new Set();
  for (const [pattern, candidates] of Object.entries(STRENGTH_PATTERNS)) {
    let winner = null;
    for (const lift of candidates) {
      if (!standards[lift]) continue;
      const best = bestPR(lift);
      if (best == null) continue;
      const ratio = best / bw;
      const lvlIdx = STRENGTH_LEVELS.indexOf(levelForRatio(standards, lift, ratio, ageFactor));
      // "Best" = highest level achieved; tiebreak by ratio-within-standard.
      const score = lvlIdx + Math.min(0.99, ratio / (standards[lift].Elite * (ageFactor || 1)));
      if (!winner || score > winner.score) {
        winner = { lift, best, ratio: Math.round(ratio * 100) / 100, level: levelForRatio(standards, lift, ratio, ageFactor), lvlIdx, score, pattern };
      }
    }
    if (winner) {
      // Continuous position within the level band (0-1) so the bar reflects how close the
      // lift is to the next tier, instead of every lift at a level rendering an identical bar.
      // World Class has no upper threshold, so extend its band 25% past the cutoff for the bar.
      const s = standards[winner.lift], f = ageFactor || 1;
      const bounds = [0, s.Novice * f, s.Intermediate * f, s.Proficient * f, s.Advanced * f, s.Exceptional * f, s.Elite * f, s.WorldClass * f, s.WorldClass * f * 1.25];
      const lo = bounds[winner.lvlIdx], hi = bounds[winner.lvlIdx + 1];
      const within = hi > lo ? Math.min(1, Math.max(0, (winner.ratio - lo) / (hi - lo))) : 1;
      const pct = Math.min(100, Math.round(((winner.lvlIdx + within) / (STRENGTH_LEVELS.length - 1)) * 1000) / 10);
      lifts.push({ lift: winner.lift, best: winner.best, ratio: winner.ratio, level: winner.level, pattern: winner.pattern, pct });
      usedLifts.add(winner.lift);
      // `cont` = the lift's CONTINUOUS level position (integer level + how far it is
      // into the band toward the next tier), the same measure the per-lift bar shows.
      // The headline score averages this — NOT the bare integer level — so the number
      // reflects real progress within a level and doesn't snap onto the level anchors
      // (why an all-Intermediate lifter used to read exactly 60).
      scoredWinners.push({ lvlIdx: winner.lvlIdx, cont: winner.lvlIdx + within, score: winner.score });
    }
  }
  if (!scoredWinners.length) return { ready: false, reason: "no_lifts" };
  // Average only the user's strongest patterns (drop the weakest few). Rank by the continuous
  // `score` (level + ratio-within-band) so ties between same-level lifts break on the closer one.
  const topWinners = scoredWinners.sort((a, b) => b.score - a.score).slice(0, STRENGTH_SCORE_TOP_N);
  const counted = topWinners.length;
  const avgIdx = topWinners.reduce((sum, w) => sum + w.cont, 0) / counted;
  const overall = STRENGTH_LEVELS[Math.round(avgIdx)] || "Untrained";
  // Curved 0-100 score — see STRENGTH_SCORE_CURVE. Interpolates between the two control points
  // straddling avgIdx (same piecewise-linear approach as the per-lift bar % below).
  const cps = STRENGTH_SCORE_CURVE;
  const lo = Math.max(0, Math.min(cps.length - 1, Math.floor(avgIdx)));
  const hi = Math.min(cps.length - 1, lo + 1);
  const t = avgIdx - lo;
  const score = Math.min(100, Math.round(cps[lo] + t * (cps[hi] - cps[lo])));
  // Map-only lifts (e.g. calf raise): give them a level for the muscle-balance body map, but
  // keep them out of `lifts`/`counted`/`overall` so they never affect the strength score.
  const mapLifts = [];
  for (const lift of STRENGTH_MAP_ONLY_LIFTS) {
    if (!standards[lift]) continue;
    const best = bestPR(lift);
    if (best == null) continue;
    mapLifts.push({ lift, level: levelForRatio(standards, lift, best / bw, ageFactor) });
  }
  // Surface any individually high-leveled lifts so single big lifts get recognised even
  // when the rounded overall is lower.
  const advancedIdx = STRENGTH_LEVELS.indexOf("Advanced");
  const topLifts = lifts.filter(l => STRENGTH_LEVELS.indexOf(l.level) >= advancedIdx)
    .sort((a, b) => STRENGTH_LEVELS.indexOf(b.level) - STRENGTH_LEVELS.indexOf(a.level));
  return { ready: true, overall, score, lifts, mapLifts, bodyweight: bw, bodyweightAgeDays, counted, sex, age, ageFactor, topLifts };
}

// Maps each body-map region to the lift(s) that best represent its strength. Abs is intentionally
// absent — no standard lift loads it directly, so it renders as "no data" rather than mirroring an
// unrelated lift. Several entries are proxies (biceps via rows, triceps via pressing, forearms via
// heavy pulls/grip) since there's no isolation standard. Calves is sourced from a map-only lift
// (see STRENGTH_MAP_ONLY_LIFTS): it shades here without counting toward the strength score.
const MUSCLE_STRENGTH_LIFTS = {
  Chest: ["Barbell Bench Press", "Incline Bench Press"],
  Shoulders: ["Overhead Press (Barbell)"],
  Quads: ["Barbell Back Squat", "Front Squat"],
  Lats: ["Barbell Row", "Deadlift"],
  Hamstrings: ["Romanian Deadlift", "Deadlift"],
  Glutes: ["Hip Thrust", "Barbell Back Squat", "Deadlift", "Romanian Deadlift"],
  Triceps: ["Barbell Bench Press", "Overhead Press (Barbell)"],
  Biceps: ["Barbell Row"],
  Forearms: ["Deadlift", "Barbell Row"],
  Traps: ["Deadlift", "Barbell Row"],
  LowerBack: ["Deadlift", "Romanian Deadlift"],
  "Rear Delts": ["Barbell Row"],
  Calves: ["Standing Calf Raise"],
};

// Per-region strength fraction (0 = Untrained, 1 = Elite) vs bodyweight standards, for the weakness
// map. Returns { ready, regionFrac:{Region:0..1}, overall, score } or { ready:false, reason }.
function muscleStrength(store, unit, sex) {
  const ss = computeStrengthScore(store, unit, sex);
  if (!ss.ready) return { ready: false, reason: ss.reason };
  const liftLevel = {};
  ss.lifts.forEach(l => {
    const lvl = STRENGTH_LEVELS.indexOf(l.level);
    liftLevel[l.lift] = lvl;
    // The score works in patterns (variants compete for one slot — only the winner appears in
    // ss.lifts), but the body map references exact lift names. Propagate the winning level to
    // every sibling in the same pattern so a region keyed on "Deadlift" still gets credit when
    // the user's best is "Sumo Deadlift" (same for Front vs Back Squat, Incline vs Flat Bench).
    for (const candidates of Object.values(STRENGTH_PATTERNS)) {
      if (candidates.includes(l.lift)) candidates.forEach(c => { liftLevel[c] = lvl; });
    }
  });
  // Map-only lifts (e.g. calf raise) shade their region without being part of the score.
  (ss.mapLifts || []).forEach(l => { liftLevel[l.lift] = STRENGTH_LEVELS.indexOf(l.level); });
  const denom = STRENGTH_LEVELS.length - 1;
  const regionFrac = {};
  for (const [region, lifts] of Object.entries(MUSCLE_STRENGTH_LIFTS)) {
    let best = null;
    lifts.forEach(lift => { if (liftLevel[lift] != null) best = Math.max(best == null ? -1 : best, liftLevel[lift]); });
    if (best != null) regionFrac[region] = best / denom;
  }
  // Imbalance checks (only when both sides have data). Flags meaningful gaps (>~0.6 / ~0.8 of
  // a level) — thresholds expressed as a fraction of denom so they stay level-equivalent
  // regardless of how many tiers STRENGTH_LEVELS has.
  const avg = (keys) => { const vs = keys.map(k => regionFrac[k]).filter(v => v != null); return vs.length ? vs.reduce((a, b) => a + b, 0) / vs.length : null; };
  const imbalances = [];
  const push = avg(["Chest", "Shoulders", "Triceps"]), pull = avg(["Lats", "Biceps"]);
  if (push != null && pull != null && Math.abs(push - pull) >= 0.6 / denom) {
    imbalances.push(push > pull ? "Pull is lagging your push" : "Push is lagging your pull");
  }
  const quad = regionFrac["Quads"], post = avg(["Hamstrings", "Glutes"]);
  if (quad != null && post != null && Math.abs(quad - post) >= 0.6 / denom) {
    imbalances.push(quad > post ? "Hamstrings/glutes lag your quads" : "Quads lag your hamstrings/glutes");
  }
  // Lower body vs upper body — a common neglect pattern worth surfacing.
  const upper = avg(["Chest", "Shoulders", "Lats", "Biceps", "Triceps"]);
  const lower = avg(["Quads", "Hamstrings", "Glutes"]);
  if (upper != null && lower != null && Math.abs(upper - lower) >= 0.8 / denom) {
    imbalances.push(upper > lower ? "Legs are lagging your upper body" : "Upper body lags your legs");
  }
  return { ready: true, regionFrac, overall: ss.overall, score: ss.score, imbalances, bodyweightAgeDays: ss.bodyweightAgeDays };
}

// Assembles a compact, structured snapshot of the user's training for the AI coach to reason
// over. Deliberately summarized (not raw dumps) to keep the prompt small and focused: recent
// sessions, top lifts + strength levels, stalls, consistency. All from data already stored.
function buildCoachContext(store, unit) {
  // `todayMs` is read twice below (the bodyweight-trend cutoff and the 7-day PR window) and was
  // never declared here — the nearest binding of that name lives inside getExerciseSessions, a
  // different function entirely. A free identifier is a ReferenceError, not undefined, and the
  // second read is unconditional, so this function ALWAYS threw. The weekly-review effect wraps
  // the call in a catch that turns it into setReviewStatus("error"), so the feature simply never
  // produced a review and nothing was logged. Same shape as the local-noon anchor used by every
  // other date helper here — never `new Date(key)`, which parses as midnight UTC.
  const todayMs = new Date(dKey() + "T12:00:00").getTime();
  const sex = store.strengthSex || "male";
  const ss = computeStrengthScore(store, unit, sex);
  const streak = calcWeeklyStreak(store.workoutDates || {}, store.weeklyTarget || 3);
  const dates = Object.keys(store.history || {}).sort().reverse();
  const recent = [];
  for (const d of dates) {
    const sessions = Object.values(store.history[d] || {});
    for (const s of sessions) {
      const exs = (s.exercises || []).map(ex => {
        const done = (ex.sets || []).filter(st => st.type !== "warmup" && (st.done === true || (st.done === undefined && parseFloat(st.reps) > 0)));
        if (!done.length) return null;
        const top = done.reduce((a, st) => (parseFloat(st.weight) || 0) > (parseFloat(a.weight) || 0) ? st : a, done[0]);
        return { name: ex.name, sets: done.length, topWeight: parseFloat(top.weight) || 0, topReps: parseFloat(top.reps) || 0 };
      }).filter(Boolean);
      if (exs.length) recent.push({ date: d, name: s.dayName || s.name || "Workout", exercises: exs });
    }
    if (recent.length >= 8) break;
  }
  // Days since each muscle was last worked — counting BOTH primary and SECONDARY involvement.
  // Without secondaries the coach falsely reports rear delts / traps / biceps / abs as "untouched
  // for weeks" even when rows, face pulls, shrugs, and presses hit them every session.
  const lastTrained = daysSinceMuscleTrained(store);
  // Effective weekly sets per muscle (secondaries count 0.5×) so the coach has hard numbers on
  // what's actually being trained — including muscles only hit as secondaries — instead of
  // inferring neglect from primary-muscle names alone.
  const _wmv = weeklyMuscleVolume(store, 7);
  const weeklyMuscleSets = {};
  for (const [m, v] of Object.entries(_wmv.byMuscle || {})) weeklyMuscleSets[_cleanMuscle(m)] = Math.round(v * 10) / 10;
  const stalls = [];
  ["Barbell Bench Press","Barbell Back Squat","Deadlift","Overhead Press (Barbell)"].forEach(l => {
    const dl = detectDeloadNeeded(store, l, unit);
    if (dl.stalled) stalls.push({ lift: l, detail: dl.reason });
  });
  const mr = muscleReadiness(store);
  const fatiguedMuscles = Object.entries(mr.readiness || {})
    .filter(([, v]) => v < 0.7).sort((a, b) => a[1] - b[1]).slice(0, 5)
    .map(([k, v]) => ({ muscle: _regionLabel(k), recoveredPct: Math.round(v * 100) }));
  const ms = muscleStrength(store, unit, sex);
  // Bodyweight trend over the last ~6 weeks — lets the coach judge stalls in context (a stalled
  // press while cutting is expected; while gaining it warrants attention).
  const _bl = [...(store.bodyLog || [])].filter(b => b.weight != null && b.date).sort((a, b) => a.date.localeCompare(b.date));
  let bodyweightTrend = null;
  if (_bl.length >= 2) {
    const cutoffMs = todayMs - 42 * 864e5;
    const window = _bl.filter(b => new Date(b.date + "T12:00:00").getTime() >= cutoffMs);
    const from = (window.length >= 2 ? window : _bl)[0], to = _bl[_bl.length - 1];
    const delta = Math.round((to.weight - from.weight) * 10) / 10;
    const days = Math.max(1, Math.round((new Date(to.date + "T12:00:00").getTime() - new Date(from.date + "T12:00:00").getTime()) / 864e5));
    bodyweightTrend = { current: to.weight, overDays: days, change: delta, direction: delta <= -1 ? "losing" : delta >= 1 ? "gaining" : "stable" };
  }
  // PRs set in the last 7 days (dedup to the heaviest per lift), in display units.
  const _weekAgoMs = todayMs - 7 * 864e5 + 1;
  const _prBest = {};
  for (const e of (store.prEvents || [])) {
    if (!e.date || new Date(e.date + "T12:00:00").getTime() < _weekAgoMs) continue;
    const w = unit === "lbs" ? e.weightLbs : cvt(e.weightLbs, "lbs", unit);
    if (!_prBest[e.name] || w > _prBest[e.name]) _prBest[e.name] = Math.round(w * 10) / 10;
  }
  const prsThisWeek = Object.entries(_prBest).map(([lift, weight]) => ({ lift, weight }));
  // The reviewed week's headline numbers (real, not AI) — power the recap stat header.
  let _wSessions = 0, _wVolume = 0, _wTop = null;
  for (const d of dates) {
    if (new Date(d + "T12:00:00").getTime() < _weekAgoMs) continue;
    for (const s of Object.values(store.history[d] || {})) {
      let counted = false;
      for (const ex of (s.exercises || [])) for (const st of (ex.sets || [])) {
        if (st.type === "warmup") continue;
        const done = st.done === true || (st.done === undefined && parseFloat(st.reps) > 0);
        if (!done) continue;
        counted = true;
        const w = cvt(parseFloat(st.weight) || 0, s.unit || unit, unit), r = parseFloat(st.reps) || 0;
        _wVolume += w * r;
        if (!_wTop || w > _wTop.w) _wTop = { w: Math.round(w * 10) / 10, r, lift: ex.name };
      }
      if (counted) _wSessions++;
    }
  }
  const weekStats = { sessions: _wSessions, volume: Math.round(_wVolume), prs: prsThisWeek.length, topSet: _wTop ? { weight: _wTop.w, reps: _wTop.r, lift: _wTop.lift } : null };
  return {
    unit, sex,
    fatiguedMuscles,
    imbalances: ms.ready ? (ms.imbalances || []) : [],
    strength: ss.ready ? { overall: ss.overall, score: ss.score, lifts: ss.lifts.map(l => ({ lift: l.lift, level: l.level, ratio: l.ratio })) } : null,
    bodyweight: ss.ready ? ss.bodyweight : null,
    bodyweightTrend,
    prsThisWeek,
    weekStats,
    consistency: { weeklyStreak: streak.count, thisWeek: streak.thisWeek, target: streak.target },
    recentSessions: recent,
    daysSinceMuscle: lastTrained,
    weeklyMuscleSets,
    stalls,
    recovery: store.recovery || null,
  };
}

// Returns the last `limit` working-set sessions for an exercise, newest first.
// Each entry: { date, unit, sets:[{w,r}], daysSince, topWeight, topReps, volume }.
function getExerciseSessions(store, exName, limit = 5) {
  const dates = Object.keys(store.history || {}).sort().reverse();
  const out = [];
  const todayMs = new Date(dKey() + "T12:00:00").getTime();
  for (const d of dates) {
    const sessions = Object.values(store.history[d] || {});
    for (const sess of sessions) {
      const ex = sess.exercises?.find(e => e.name === exName);
      if (!ex) continue;
      const doneSets = (ex.sets || []).filter(s =>
        s.type !== "warmup" &&
        (s.done === true || (s.done === undefined && parseFloat(s.reps) > 0))
      );
      if (!doneSets.length) continue;
      const sets = doneSets.map(s => ({ w: parseFloat(s.weight) || 0, r: parseFloat(s.reps) || 0 }));
      const topWeight = Math.max(...sets.map(s => s.w));
      const topReps = Math.max(...sets.filter(s => s.w === topWeight).map(s => s.r), 0);
      const volume = sets.reduce((a, s) => a + s.w * s.r, 0);
      const dMs = new Date(d + "T12:00:00").getTime();
      out.push({
        date: d, unit: sess.unit || "lbs", sets,
        daysSince: Math.max(0, Math.floor((todayMs - dMs) / 86400000)),
        topWeight, topReps, volume,
      });
      if (out.length >= limit) return out;
    }
  }
  return out;
}

// HAS THIS EXERCISE MOVED FORWARD AT ALL? — the one question every stall test has to answer, and
// the one the old ones kept getting wrong because they only ever looked at the TOP set.
//
// `topReps` is the reps of the heaviest set, so a lifter who opens 40x12 every time and adds his
// progress further down the run — 40x12, 40x12, 40x10, 40x9 becoming 40x12, 40x12, 40x10, 40x10 —
// has a topReps series that is dead flat while every other set climbs. Measured on Mo's real
// Lateral Raises history (Jul 20 / Jul 30 / Aug 3): top set 12/12/12, total volume 1640/1720/1760.
// The banner called that a plateau and told him to drop 5 lbs on a session that was his best yet.
//
// So ask four questions, not one, and count ANY of them as progress: more weight, more reps on the
// top set, more total reps, more volume. Volume and total reps are what see the back half of a run.
//
// COMPARE THE BEST OF THE LAST TWO AGAINST THE BEST OF THE REST, not the newest against everything.
// One short session — three sets instead of four because the gym was closing — drops volume through
// the floor without meaning anything about strength, and a newest-vs-best test reads that as a
// stall on its own. Using the better of the two most recent absorbs a single off day. It also means
// a lifter who peaked one session ago and is now sliding gets a pass for one more session; that is
// the deliberate direction to err, because the cost of a missed stall is silence and the cost of a
// false one is being told to take weight off a bar you just set a record on.
function exerciseProgressed(sessions, unit) {
  if (sessions.length < 2) return true;   // not enough to call anything a plateau
  const series = sessions.map(s => ({
    // Volume and reps are compared across sessions, so both sides must be in ONE unit — a history
    // logged in kg read by an lbs user would otherwise invent progress out of the conversion.
    w: cvt(s.topWeight, s.unit, unit),
    topReps: s.topReps || 0,
    totalReps: (s.sets || []).reduce((a, x) => a + (x.r || 0), 0),
    vol: cvt(s.volume, s.unit, unit),
  }));
  const recent = series.slice(0, 2), older = series.slice(2);
  if (!older.length) return true;
  const best = (arr, k) => Math.max(...arr.map(x => x[k]));
  return ["w", "topReps", "totalReps", "vol"].some(k => best(recent, k) > best(older, k) + 1e-6);
}

// Deload / stall detection — THE one verdict for an exercise. The plateau banner and every set's
// progression chip both read it, so they cannot contradict each other.
//
// They used to be two separate tests and they disagreed constantly. The banner asked whether the
// top set was flat; each chip asked whether ITS OWN set index had gained reps since three sessions
// ago. On the same screen that produced this note, set 1 (12/12/12) said "deload to 35" while set 2
// (12/12/11) said "40x13" directly beneath it — opposite advice about the same exercise, one row
// apart, because the two sets had different rep histories. A stall is a property of the LIFT, not
// of a row in a table.
//
// `repsTarget` is optional. Pass it wherever the verdict sits next to per-set advice: without a
// target "stuck" has no meaning (holding 100x12 on an accessory for a month is a deliberate steady
// load, not a failure), and if the lifter is already at or past the top of the range then the
// honest advice is to ADD weight — which is exactly what the chips say, and the banner used to
// contradict. The AI coach passes nothing, deliberately: it writes prose about the big compounds
// with no chip beside it to disagree with, and a flat bench for four sessions is a stall whatever
// a program has written in its reps column.
function detectDeloadNeeded(store, exName, unit, repsTarget = null) {
  // Require 4 flat sessions (not 3) so the plateau banner only fires on a genuine, sustained
  // stall — fewer false positives, less nagging.
  const sessions = getExerciseSessions(store, exName, 6);
  if (sessions.length < 4) return { stalled: false };
  const norm = sessions.map(s => ({
    wU: cvt(s.topWeight, s.unit, unit),
    // `Math.max(1, …)`: a set marked done with a blank reps field gives topReps 0, and epley1RM
    // rightly refuses to estimate from that — but a 0 dropped into this series reads as a
    // catastrophic strength LOSS and can fire a false "deload" banner telling the lifter to drop
    // weight they haven't actually lost. Treat it as the single it effectively is (the weight
    // itself), which is what this line computed before the estimator was consolidated.
    e1rm: epley1RM(cvt(s.topWeight, s.unit, unit), Math.max(1, s.topReps || 0), 12),
  }));
  const recentRaw = sessions.slice(0, 4);
  const recent = norm.slice(0, 4);
  const topWeights = recent.map(s => s.wU);
  const maxTop = Math.max(...topWeights);
  const minTop = Math.min(...topWeights);
  const weightFlat = (maxTop - minTop) < (unit === "lbs" ? 5 : 2.5);
  const e1rms = recent.map(s => s.e1rm);
  const e1rmNotProgressing = e1rms[0] <= Math.max(...e1rms.slice(1)) + 0.01;
  // Progress anywhere in the exercise — not just on the top set — means this is not a plateau.
  const progressed = exerciseProgressed(recentRaw, unit);
  // At or past the top of the target range at a flat weight is the textbook cue to ADD load. That
  // is what the chips advise, so the banner must not be telling him to take load off.
  const range = repsTarget ? parseRepRange(repsTarget) : null;
  // "AT the top of the range" is a question about the LAST session, not about the window. The
  // first cut took `Math.max` over all four, so one good session four weeks ago suppressed the
  // banner for a lifter who had since fallen back and stuck: range 5-8, a session at 185x8 then
  // three at 185x5, and the plateau went unreported because of the 8 he could no longer do.
  // Reps sliding backwards at a flat weight is a stall in the plainest sense.
  const earnedTheJump = !!range && range.high > 0 && (recentRaw[0]?.topReps || 0) >= range.high;
  if (weightFlat && !progressed && e1rmNotProgressing && !earnedTheJump) {
    const dl = unit === "lbs" ? Math.round((maxTop * 0.9) / 5) * 5 : Math.round((maxTop * 0.9) / 2.5) * 2.5;
    return {
      stalled: true,
      sessions: recent.length,
      topWeight: maxTop,
      deloadWeight: dl,
      reason: `Stalled at ${maxTop} ${unit} for ${recent.length} sessions`,
      suggestion: `Try a deload: drop to ~${dl} ${unit} and rebuild with clean reps`,
    };
  }
  return { stalled: false };
}

// Progressive overload — double progression model
// Returns { type, weight, reps, note, deltaWeight, deltaReps, reason }
// The smallest jump a real gym can make. Everything else snaps to a multiple of this.
function plateStep(unit) { return unit === "lbs" ? 5 : 2.5; }

// How much to add, scaled to the load. A flat +5 lb is ~1.5% on a 315 deadlift (too timid, you
// stall on the calendar not the bar) and 20% on a 25 lb lateral raise (impossible to sustain).
// ~2.5% per session is the standard week-to-week jump; snap it to a real plate and clamp so the
// suggestion never becomes a 4-plate leap on a heavy lift.
function loadIncrement(weight, unit) {
  const step = plateStep(unit);
  const snapped = Math.round((weight * 0.025) / step) * step;
  return Math.max(step, Math.min(step * 4, snapped));
}

// The last N sessions of one exercise, newest first, reduced to the set at `setIndex` (falling
// back to that session's last working set). This is what makes the engine trend-aware instead of
// judging everything off a single previous session — without it, three failed attempts at the same
// weight each produce the same cheerful "+5" and the user never gets told to back off.
function getExerciseTrend(store, exName, unit, setIndex = 0, n = 4) {
  const out = [];
  const dates = Object.keys(store.history || {}).sort().reverse();
  const todayMs = new Date(dKey() + "T12:00:00").getTime();
  for (const d of dates) {
    if (out.length >= n) break;
    for (const sess of Object.values(store.history[d] || {})) {
      const ex = sess.exercises?.find(e => e.name === exName);
      if (!ex) continue;
      const working = (ex.sets || []).filter(s => s.type !== "warmup" &&
        (s.done === true || (s.done === undefined && parseFloat(s.reps) > 0)));
      if (!working.length) continue;
      const s = working[setIndex] || working[working.length - 1];
      const w = cvt(parseFloat(s.weight) || 0, sess.unit || "lbs", unit);
      if (!w) continue;
      const rpe = parseFloat(s.rpe);
      out.push({ date: d, w, r: parseFloat(s.reps) || 0, rpe: (!isNaN(rpe) && rpe > 0) ? rpe : null,
        daysSince: Math.max(0, Math.floor((todayMs - new Date(d + "T12:00:00").getTime()) / 86400000)) });
      break;
    }
  }
  return out;
}

function suggestNextSet(store, exName, repsTarget, unit, setIndex = 0) {
  const last = getLastExerciseSession(store, exName);
  if (!last) return null;

  const range = parseRepRange(repsTarget);
  const lastInUserUnit = last.sets.map(s => ({ w: cvt(s.w, last.unit, unit), r: s.r }));
  const setMatch = lastInUserUnit[setIndex] || lastInUserUnit[lastInUserUnit.length - 1];
  if (!setMatch || !setMatch.w) return null;

  const lastWeight = setMatch.w;
  const lastReps = setMatch.r;
  const step = plateStep(unit);
  const inc = loadIncrement(lastWeight, unit);
  const trend = getExerciseTrend(store, exName, unit, setIndex, 4);
  const lastRpe = trend[0]?.rpe ?? null;
  // RPE 9.5+ is a grinder — at or next to failure. Adding load on top of that is how people get
  // hurt and how a program stalls; consolidate instead. RPE <=6.5 means there was plenty left.
  const grinder = lastRpe != null && lastRpe >= 9.5;
  const easy = lastRpe != null && lastRpe <= 6.5;
  // On light isolation work the smallest plate is a huge relative jump (5 lb on a 20 lb raise is
  // 25%). Earn it with reps first, and only jump once you're clear of the top of the range.
  const jumpIsBig = lastWeight > 0 && (step / lastWeight) > 0.10;

  // Deload if it's been 14+ days
  if (last.daysSince >= 14) {
    const dl = unit === "lbs" ? Math.round((lastWeight * 0.9) / 5) * 5 : Math.round((lastWeight * 0.9) / 2.5) * 2.5;
    return {
      type: "deload",
      weight: dl,
      reps: range ? range.low : lastReps,
      note: "Deload (off " + last.daysSince + "d)",
      deltaWeight: dl - lastWeight,
      reason: "Back after a break — start lighter",
    };
  }

  // STALL — ONE verdict for the whole exercise, shared with the plateau banner.
  //
  // This used to run its own test per SET INDEX: "has this row gained reps since three sessions
  // ago". Two rows of the same exercise therefore reached opposite conclusions routinely — set 1
  // steady at 12 reps said "deload to 35" while set 2, which had gone 11 → 12, said "40x13" in the
  // row directly below. Whether you have plateaued is a fact about the lift; asking it once and
  // handing every row the same answer is the only way the screen can be coherent.
  //
  // Still gated on `range` for the reason the per-set version was: without a target there is
  // nothing to be stuck short of. `detectDeloadNeeded` re-checks the exercise-wide progress
  // signals (total reps and volume, not just the top set), so a lifter adding reps anywhere in the
  // run is never told to back off.
  if (range && detectDeloadNeeded(store, exName, unit, repsTarget).stalled) {
    // Scale from THIS set's own weight rather than the exercise's top weight — on a descending or
    // drop-set arrangement a single flat number for every row would be a different workout, not a
    // deload of the one being done.
    const dl = Math.max(step, Math.round((lastWeight * 0.9) / step) * step);
    return {
      type: "deload",
      weight: dl,
      reps: range.high,
      note: `−${+(lastWeight - dl).toFixed(1)} ${unit}`,
      deltaWeight: dl - lastWeight,
      reason: `Stuck at ${lastWeight} ${unit} for 4 sessions — drop 10% and build back`,
    };
  }

  // Double progression — judged PER-SET against the matching set from last session.
  // Old logic checked `every set hit the range top`, which meant a fatigued last set
  // (e.g. 5 reps on a 6-8 range) blocked the suggestion to add weight on set 1 — even
  // when set 1 cleanly hit 8 last time. Real progression is per-set.
  if (range) {
    const setHitTop = lastReps >= range.high;
    // Hit the top but it was a grinder — bank the rep quality before adding load.
    if (setHitTop && grinder) {
      return {
        type: "match",
        weight: lastWeight,
        reps: lastReps,
        note: "repeat",
        deltaReps: 0,
        reason: `Last one was an RPE ${lastRpe} grind — repeat it before adding weight`,
      };
    }
    // Light isolation work: keep earning reps until you're clearly past the top of the range,
    // because the smallest jump available is a >10% increase in load.
    if (setHitTop && jumpIsBig && lastReps < range.high + 2) {
      const target = Math.min(range.high + 2, lastReps + 1);
      return {
        type: "reps",
        weight: lastWeight,
        reps: target,
        note: "same weight",
        deltaReps: target - lastReps,
        reason: `+${step} ${unit} is a big jump here — get ${target} first`,
      };
    }
    if (setHitTop) {
      // The matching set hit the top of the range last time → add weight.
      // If they went way past the top (e.g. 15 reps on a 5-8 range), bump weight
      // but keep reps realistic instead of dropping all the way to range.low.
      const overshoot = lastReps - range.high;
      if (overshoot >= 4) {
        return {
          type: "weight",
          weight: lastWeight + inc,
          reps: Math.max(range.high, lastReps - 2),
          note: `+${inc} ${unit}`,
          deltaWeight: inc,
          reason: `Way above target reps — add ${inc} ${unit}, keep reps high`,
        };
      }
      // Plenty left in the tank — take a double jump rather than creeping.
      const bump = easy ? Math.min(step * 4, inc * 2) : inc;
      return {
        type: "weight",
        weight: lastWeight + bump,
        reps: range.low,
        note: `+${bump} ${unit}`,
        deltaWeight: bump,
        reason: easy
          ? `Hit ${range.high} at RPE ${lastRpe} — add ${bump} ${unit}`
          : `Hit ${range.high} on this set — add ${bump} ${unit}`,
      };
    } else {
      // Same weight, push for more reps — but never suggest a jump of more than 2 reps
      // over last session ("did 8 → do 14" isn't progression advice). If the program's
      // range starts far above what they did, build toward it gradually.
      // A 0-rep "last session" carries no information — getLastExerciseSession accepts a set
      // ticked done with a blank reps box, and `parseFloat("") || 0` makes it 0. The `lastReps + 2`
      // cap then wins the min() and the app advises "Build toward 8 — aim for 2". Same family as
      // the sim_deload0 fix, which guarded detectDeloadNeeded and left this path alone: when
      // there's no real rep count, start at the bottom of the range instead of two above nothing.
      const target = lastReps > 0
        ? Math.min(range.high, Math.max(range.low, lastReps + 1), lastReps + 2)
        : range.low;
      return {
        type: "reps",
        weight: lastWeight,
        reps: target,
        note: `same weight`,
        deltaReps: target - lastReps,
        reason: target > lastReps
          ? (target < range.low ? `Build toward ${range.low} — aim for ${target}` : `Push for ${target} reps`)
          : `Match last session`,
      };
    }
  }

  // No range: simple bump on +2 reps — unless it was a grind, or the only available jump is
  // disproportionate to the load (same reasoning as the ranged path above).
  if (lastReps >= 10 && !grinder && !jumpIsBig) {
    return {
      type: "weight",
      weight: lastWeight + inc,
      reps: Math.max(lastReps - 2, 5),
      note: `+${inc} ${unit}`,
      deltaWeight: inc,
      reason: `Strong last time — add ${inc} ${unit}`,
    };
  }
  if (lastReps >= 10 && grinder) {
    return {
      type: "match",
      weight: lastWeight,
      reps: lastReps,
      note: "repeat",
      deltaReps: 0,
      reason: `RPE ${lastRpe} last time — repeat before adding weight`,
    };
  }
  return {
    type: "match",
    weight: lastWeight,
    reps: lastReps + 1,
    note: `+1 rep`,
    deltaReps: 1,
    reason: `Push for one more rep`,
  };
}

// "Swipe the keyboard down" — the OS-level drag-to-dismiss gesture Mo asked for isn't reliably
// reachable in a WKWebView. Checks the TAG, not a ref, so it only ever blurs a genuine
// <input>/<textarea> (the set-weight/reps fields are DIVs driven by the in-app NumberPad on
// purpose, and never focus a real input at all, so this can't interrupt them).
function blurIfTextInput() {
  const el = typeof document !== "undefined" ? document.activeElement : null;
  if (el && (el.tagName === "INPUT" || el.tagName === "TEXTAREA") && typeof el.blur === "function") el.blur();
}

// First cut of "swipe to dismiss" fired on the SCROLL event of specific lists — Mo reported it
// not working. Two real gaps: a short results list never generates a scroll event at all (nothing
// to scroll), and NumberPad's fields are DIVs with no scrollable list nearby for a scroll handler
// to even attach to. This tracks the raw TOUCH instead, so it fires on drag distance regardless of
// whether anything actually scrolls — same mechanism a real interactive keyboard dismiss uses.
// Ref-driven (the gesture-perf pattern this file uses everywhere else): no re-render per frame,
// just two cheap ref reads, and it never calls preventDefault/stopPropagation, so it can't fight
// the scroll or any other gesture — it only ever ADDS a dismiss on top of whatever already happens.
function useSwipeDismiss(onDismiss) {
  const startY = useRef(null);
  const firedRef = useRef(false);
  return {
    onTouchStart: e => {
      // Never arm over a region that owns its own gesture — SetRow's swipe-to-delete/complete is
      // the one that matters here (`[data-no-tab-swipe]`, same bail list `handleSwipeStart` uses
      // for the tab swipe). This hook's own onTouchMove never calls preventDefault/stopPropagation,
      // so on its own it can't out-and-out block anything — but wiring it onto the exercise
      // scroller (an ancestor of every SetRow) gave that ancestor an active touchmove listener it
      // never had before, and Mo reported the swipe-to-delete gesture "messed up" right after that
      // shipped. Leaving startY unset here means this hook is a guaranteed no-op for any touch that
      // starts on a set row, which removes the ancestor listener from that gesture's path entirely
      // rather than relying on it staying inert.
      if (e.target && e.target.closest && e.target.closest("[data-no-tab-swipe]")) { startY.current = null; return; }
      startY.current = e.touches?.[0]?.clientY ?? null; firedRef.current = false;
    },
    onTouchMove: e => {
      if (startY.current == null || firedRef.current) return;
      const y = e.touches?.[0]?.clientY;
      if (y == null) return;
      if (y - startY.current > 14) { firedRef.current = true; onDismiss(); }
    },
  };
}

// Haptic helpers - tiered patterns
// Haptic feedback vocabulary
//
// Each `kind` produces a different vibration pattern. The goal is for users
// to start subconsciously associating certain feels with certain actions —
// the way iOS uses crisp/soft/heavy for different interactions.
//
// Web Vibration API takes either a single ms or an array of [vibrate, pause, vibrate, ...].
// Most users on iOS won't feel these (Safari doesn't support navigator.vibrate)
// but Android and Capacitor-wrapped builds will. The patterns degrade gracefully.
export function haptic(kind) {
  // Native haptics (iOS/Android) via the Capacitor Haptics plugin, reached through the runtime
  // global so there's no build-time import (keeps the web bundle clean). Real Taptic Engine
  // feedback — far better than web vibration, which iOS Safari/WKWebView ignores entirely.
  try {
    const Cap = (typeof window !== "undefined") ? window.Capacitor : null;
    if (Cap?.isNativePlatform?.() && Cap.Plugins?.Haptics) {
      const H = Cap.Plugins.Haptics;
      const impact = (style) => { try { H.impact({ style }); } catch {} };
      const notify = (type) => { try { H.notification({ type }); } catch {} };
      switch (kind) {
        case "tap": case "lock": case "modal-out": case "back": impact("LIGHT"); break;
        case "light": case "modal-in": case "tab": case "undo": case "refresh": impact("LIGHT"); break;
        case "medium": impact("MEDIUM"); break;
        case "heavy": impact("HEAVY"); break;
        case "complete": notify("SUCCESS"); break;
        case "rest-end": notify("WARNING"); break;
        case "delete": case "warn": notify("WARNING"); break;
        case "error": notify("ERROR"); break;
        case "success": notify("SUCCESS"); break;
        case "pr-small": notify("SUCCESS"); break;
        case "pr": notify("SUCCESS"); break;
        case "pr-big": notify("SUCCESS"); setTimeout(() => notify("SUCCESS"), 130); break;
        default: impact("LIGHT");
      }
      return; // handled natively — don't also fire web vibration
    }
  } catch {}
  try {
    if (!navigator.vibrate) return;
    switch (kind) {
      // ── Standard taps ───────────────────────────────────────────────
      case "tap":      navigator.vibrate(8); break;   // generic button press, very subtle
      case "light":    navigator.vibrate(12); break;  // chip/toggle selection
      case "medium":   navigator.vibrate(20); break;  // set checked (not last)
      case "heavy":    navigator.vibrate(35); break;  // important confirmation

      // ── Workout flow ────────────────────────────────────────────────
      case "complete": navigator.vibrate(28); break;          // last set of exercise done
      case "rest-end": navigator.vibrate([60, 80, 60]); break; // rest timer fires
      case "lock":     navigator.vibrate(6); break;            // swipe-to-done lock detent

      // ── PR celebration — tiered by magnitude ────────────────────────
      case "pr-small": navigator.vibrate([15, 30, 15, 30, 40]); break;            // PR by 0-5%
      case "pr":       navigator.vibrate([20, 40, 20, 40, 80]); break;            // standard PR
      case "pr-big":   navigator.vibrate([25, 30, 25, 30, 25, 30, 120]); break;   // PR by 10%+

      // ── Navigation ──────────────────────────────────────────────────
      case "modal-in":  navigator.vibrate(10); break;  // open a sheet/modal
      case "modal-out": navigator.vibrate(6); break;   // dismiss a sheet/modal
      case "back":      navigator.vibrate(8); break;   // navigate backward
      case "tab":       navigator.vibrate(12); break;  // switch tab

      // ── Destructive ─────────────────────────────────────────────────
      case "delete":   navigator.vibrate([30, 30, 30]); break;     // confirm delete
      case "undo":     navigator.vibrate(12); break;               // undo
      case "warn":     navigator.vibrate([30, 60, 30]); break;     // confirm warning

      // ── Status ──────────────────────────────────────────────────────
      case "success":  navigator.vibrate([15, 30, 30]); break;     // generic success (post sent etc)
      case "error":    navigator.vibrate([40, 60, 40, 60, 40]); break; // operation failed
      case "refresh":  navigator.vibrate([10, 20, 10]); break;     // pull-to-refresh tick

      default:         navigator.vibrate(15);
    }
  } catch {}
}

// ═════════════════════════════════════════════════════════════════════════════
// LOCAL NOTIFICATIONS — native rest-timer alert that fires even when the app is
// backgrounded or the phone is locked. A JS timer can't run in the background on iOS
// (the WebView is suspended), so instead we SCHEDULE a local notification for when the
// rest period ends, and cancel it if rest finishes/cancels early. Reached via the runtime
// Capacitor global so there's no build-time import (keeps the web bundle clean).
// ═════════════════════════════════════════════════════════════════════════════
function nativeLocalNotifs() {
  const Cap = (typeof window !== "undefined") ? window.Capacitor : null;
  if (Cap?.isNativePlatform?.() && Cap.Plugins?.LocalNotifications) return Cap.Plugins.LocalNotifications;
  return null;
}
function nativeShare() {
  const Cap = (typeof window !== "undefined") ? window.Capacitor : null;
  if (Cap?.isNativePlatform?.() && Cap.Plugins?.Share) return Cap.Plugins.Share;
  return null;
}
// Share text/a link. Native builds use the @capacitor/share plugin (the web `navigator.share`
// is unreliable inside the iOS WKWebView — it can silently no-op). Web falls back to
// navigator.share, then to copying the URL so the button ALWAYS does something visible.
// `onCopied` fires when we fell back to clipboard so the caller can toast "copied".
// A dismissed share sheet is a user CHOICE, not a failure: @capacitor/share rejects with
// "Share canceled" and web navigator.share rejects with an AbortError. Treat those as "done"
// so we don't pop a second sheet or copy a link the user chose not to share.
function _shareCancelled(e) {
  return !!e && (e.name === "AbortError" || /cancel/i.test(e.message || ""));
}
export async function shareLink({ title, text, url } = {}, onCopied) {
  const S = nativeShare();
  if (S) {
    try { await S.share({ title, text, url, dialogTitle: title }); return; }
    catch (e) { if (_shareCancelled(e)) return; /* real failure — fall through to web paths */ }
  }
  try {
    if (typeof navigator !== "undefined" && navigator.share) {
      await navigator.share({ title, text, url });
      return;
    }
  } catch (e) { if (_shareCancelled(e)) return; /* unsupported — fall through to copy */ }
  const copyTarget = url || text;
  if (copyTarget && typeof navigator !== "undefined" && navigator.clipboard) {
    try { await navigator.clipboard.writeText(copyTarget); if (onCopied) onCopied(); } catch (e) {}
  }
}

// API base — on the web the serverless function is served at a relative path; inside a native
// Capacitor build there's no local server, so AI calls must hit the deployed origin in full.
const API_BASE = (() => {
  const Cap = (typeof window !== "undefined") ? window.Capacitor : null;
  return Cap?.isNativePlatform?.() ? "https://spotr-drab.vercel.app" : "";
})();
export function aiEndpoint() { return API_BASE + "/api/ai"; }
// /api/ai requires a signed-in Supabase session — the proxy verifies the token server-side
// so the Anthropic key can't be farmed by strangers hitting the URL directly. Returns null
// for guests; callers must degrade gracefully (table-program fallback / sign-in note).
export function aiAuthHeaders() {
  try {
    const tok = loadSession()?.access_token;
    return tok ? { "Content-Type": "application/json", Authorization: `Bearer ${tok}` } : null;
  } catch (e) { return null; }
}

// ═════════════════════════════════════════════════════════════════════════════
// HEALTHKIT — recovery signals (iOS only, native build). Reads HRV, resting heart
// rate, and last night's sleep so the AI coach can factor recovery into advice.
// Uses the @capgo/capacitor-health plugin (Capacitor 8, SPM). Reached through the
// runtime Capacitor global so the web bundle stays clean and degrades gracefully.
// ═════════════════════════════════════════════════════════════════════════════
// ── Body battery (v1) ─────────────────────────────────────────────────────────
// A Garmin-style 0-100 energy estimate, honest about what an iPhone can know:
//   charge:   morning level from the recovery score (HRV/RHR/sleep vs baseline)
//   drain:    logged workouts (volume + intensity), today's steps/active energy,
//             and a small baseline awake drain
// No all-day heart-rate stream (that needs a watch), so no intra-day stress drain.
// ACUTE : CHRONIC WORKLOAD RATIO — Garmin's "training load", and the best-established
// injury-risk signal in sports science. It compares what you've done THIS week against what your
// body is conditioned for (the 28-day average). A sharp spike is what hurts people, not hard
// training per se.
//
// Load is session volume normalised to one unit. Absolute magnitude doesn't matter — this is a
// ratio of a lifter against their own history, so bodyweight/exercise selection cancel out.
//
// Returns null rather than a misleading number when there isn't enough history to mean anything:
// the chronic average is the denominator, and four sessions spread over ten days is not a
// "28-day average". Bands are the standard ones (0.8 / 1.3 / 1.5).
// Guards. These exist to make the function REFUSE rather than mislead, and the first version of
// them was defeated by a single old row: `oldestMs` was taken over ALL history while the sums came
// only from the 28-day window, so six sessions on ONE day plus one row from 400 days ago passed
// every check and returned "4.00 — Spike — this is where injuries happen". A confident red injury
// warning computed from one training day is the worst failure this screen can have, and anyone
// with imported history who comes back from a break hits it. So the checks now all look INSIDE
// the window, and the chronic baseline must have older days in it to be a baseline at all.
const ACWR_MIN_SESSIONS = 6;      // ...in the 28-day window
const ACWR_MIN_DAYS = 4;          // ...spread over at least this many distinct days
const ACWR_MIN_OLDER_DAYS = 2;    // ...at least this many of them OUTSIDE the acute week
function trainingLoadRatio(store, unit = "lbs") {
  const hist = store?.history || {};
  // Bucket by CALENDAR DAY, not by elapsed milliseconds. Anchoring both ends at local noon makes
  // today = 0 and yesterday = 1 whatever the clock says; the previous version compared a noon
  // timestamp against `Date.now()`, so before local noon today's own session had a NEGATIVE age
  // and was silently dropped by the future-date guard — the ratio ignored the morning workout that
  // most changes it, then jumped a band at 12:00 with no new data. Noon anchoring also absorbs DST
  // (a 23- or 25-hour day still rounds to one day apart).
  const nd = new Date();
  const todayNoon = new Date(nd.getFullYear(), nd.getMonth(), nd.getDate(), 12).getTime();
  const dayMs = 864e5;
  let acute = 0, chronic = 0, sessions28 = 0;
  const daysInWindow = new Set(), olderDays = new Set();
  for (const [dk, day] of Object.entries(hist)) {
    const ts = new Date(dk + "T12:00:00").getTime();
    if (isNaN(ts)) continue;
    const ageDays = Math.round((todayNoon - ts) / dayMs);
    if (ageDays < 0 || ageDays > 28) continue;      // future-dated rows and anything older
    let dayHadVolume = false;
    for (const sess of Object.values(day || {})) {
      const v = cvt(sessionVolume(sess), sess.unit || "lbs", unit);
      if (v <= 0) continue;
      chronic += v; sessions28++; dayHadVolume = true;
      if (ageDays <= 7) acute += v;
    }
    if (dayHadVolume) { daysInWindow.add(ageDays); if (ageDays > 7) olderDays.add(ageDays); }
  }
  if (sessions28 < ACWR_MIN_SESSIONS || daysInWindow.size < ACWR_MIN_DAYS
      || olderDays.size < ACWR_MIN_OLDER_DAYS || chronic <= 0) return null;
  const acutePerDay = acute / 7;
  const chronicPerDay = chronic / 28;
  if (chronicPerDay <= 0) return null;
  const ratio = Math.round((acutePerDay / chronicPerDay) * 100) / 100;
  const band =
    ratio < 0.8 ? { status: "low",     label: "Detraining",  note: "Well under your usual load — an easy week is fine, but a longer dip loses fitness." } :
    ratio <= 1.3 ? { status: "optimal", label: "Sweet spot",  note: "This week matches what your body is conditioned for." } :
    ratio <= 1.5 ? { status: "caution", label: "Ramping up",  note: "Noticeably above your usual — fine briefly, worth easing if it holds." } :
                   { status: "high",    label: "Spike",       note: "Well above what you're conditioned for. This is where injuries happen." };
  return { ratio, acutePerDay: Math.round(acutePerDay), chronicPerDay: Math.round(chronicPerDay), sessions28, ...band };
}

// Days since each muscle was last trained (primary + secondary credit), keyed by muscle name.
// ONE definition: the coach summary needs it and so does the readiness card, and it must be a
// CALENDAR-day count anchored at local noon on both ends — deriving it from muscleReadiness's
// fatigue timestamps instead gave 0 days for a session logged yesterday, because those timestamps
// exist to decay fatigue, not to count days.
// Display name for an internal muscle key. Module-level because two callers need it now (the
// coach summary and the readiness card); it used to be a local const inside one function.
const _cleanMuscle = (m) => ({ RearDelts: "Rear Delts", LowerBack: "Lower Back" }[m] || m);

function daysSinceMuscleTrained(store) {
  const out = {};
  const todayMs = new Date(dKey() + "T12:00:00").getTime();
  const hist = store?.history || {};
  // Newest first, so the first time a muscle is seen is its most recent session.
  for (const d of Object.keys(hist).sort().reverse()) {
    const ts = new Date(d + "T12:00:00").getTime();
    if (isNaN(ts)) continue;
    const daysAgo = Math.max(0, Math.round((todayMs - ts) / 86400000));
    for (const s of Object.values(hist[d] || {})) {
      for (const ex of (s.exercises || [])) {
        const worked = (ex.sets || []).some(st => st.type !== "warmup"
          && (st.done === true || (st.done === undefined && parseFloat(st.reps) > 0)));
        if (!worked) continue;
        const muscles = new Set();
        const p = resolveMuscle(ex.name); if (p) muscles.add(p);
        for (const sec of getExerciseSecondaries(ex.name)) muscles.add(_cleanMuscle(sec));
        for (const m of muscles) if (out[m] == null) out[m] = daysAgo;
      }
    }
  }
  return out;
}

// What ONE session costs the battery. Used by the headline number AND the 24h curve — they had
// drifted (the curve still charged the old 6 + 0.9/set after the headline moved to 4 + 0.6/set),
// so the chart dived to ~10 while the number beside it read 23. Same class as every other
// duplicated formula in this file: one definition, both callers.
function sessionDrain(sets, avgRpe) {
  return Math.max(4, Math.min(24, Math.round(4 + sets * 0.6 + (avgRpe ? (avgRpe - 7) * 2 : 0))));
}

// DAYTIME RECOVERY. Garmin's battery climbs back during calm periods because a watch feeds it a
// continuous heart-rate stream. We don't have that — but HealthKit's per-hour step/energy buckets
// are enough to tell a still afternoon from a walk, which is the distinction that matters.
//
// Only counted when the buckets were synced TODAY: without fresh data we cannot tell "resting"
// from "no data", and assuming rest would hand a free recharge to everyone without a watch. A
// missing bucket for a past hour DOES count as still (a quiet hour records nothing), but only once
// some other bucket today has data — that proves the read actually returned something.
const REST_STEPS_PER_H = 250;   // sedentary; a walk to the kitchen won't break this
const REST_KCAL_PER_H = 40;     // active energy, above resting burn
// "You were demonstrably up and moving in this hour." Used by BOTH sleep gates — the bedtime one
// that pushes an estimated bedtime later, and the wake one that pulls an estimated wake earlier.
// It is one constant on purpose: two copies of the same threshold drift, and these two gates have
// to agree about what counts as awake or they will disagree about where the day starts.
const AWAKE_STEPS_PER_H = 120;
const REST_RECHARGE_PER_H = 2;  // net ≈ +1.1/h once the 0.9/h awake drain is netted off
function restfulHourRecharge(store, hourStartMs, todayKey) {
  if (store?.activityHourlyDate !== todayKey) return 0;
  const hourly = store.activityHourly;
  if (!hourly) return 0;
  const anyData = Object.values(hourly).some(a => a && (a.steps || a.kcal));
  if (!anyData) return 0;
  const d = new Date(hourStartMs);
  const k = dateKeyOf(d);
  if (k !== todayKey) return 0;   // buckets are hour-of-day for TODAY only
  const a = hourly[d.getHours()];
  const steps = a?.steps || 0, kcal = a?.kcal || 0;
  if (steps > REST_STEPS_PER_H || kcal > REST_KCAL_PER_H) return 0;
  return REST_RECHARGE_PER_H;
}

// A HARD CEILING MAKES THE TOP OF THE SCALE FLAT, AND A FLAT SCALE STOPS SAYING ANYTHING.
// Activity drain was `Math.min(18, raw)`, and raw hits 18 at roughly 14k steps plus 880 kcal —
// a long hike or a busy shift on your feet, not an outlier. Measured on the shipped code, every
// one of these reported the SAME Body Battery: 14.6k steps, 22k, 36.6k, 58.5k, 87.8k. A moderate
// day and an ultramarathon were indistinguishable, and the chart agreed with the number only
// because both had adopted the same flat model.
//
// So: linear up to the knee, then compressed but still RISING, asymptotic to `max`. Diminishing
// returns are the honest shape here — the tenth hour on your feet does cost less than the first —
// but they should be diminishing, not zero.
//   raw   9 -> 9.0     (an ordinary day is untouched; the knee is above where most days land)
//   raw  18 -> 17.0     ~14.6k steps
//   raw  27 -> 22.3     ~22k steps
//   raw  45 -> 26.6     ~36.6k steps
//   raw 107 -> 29.8     ~88k steps
// Both computeBodyBattery and computeBodyBatteryTimeline go through this — the whole point of
// the previous round of fixes was that the headline and the chart must share one model.
// Linear to `knee`, then compressed but still RISING, asymptotic to `max`. Used for BOTH daily
// drains, because a hard ceiling makes the top of a scale flat and a flat scale stops saying
// anything — which is the same complaint twice, once about steps and once about training.
function softCap(raw, knee, max) {
  if (!(raw > knee)) return Math.max(0, raw || 0);
  const span = max - knee;
  return knee + span * (1 - Math.exp(-(raw - knee) / span));
}
// PER HOUR, the same shape as the daily cap. The curve used a hard `Math.min(6, …)`, which is a
// flat ceiling on an hour exactly as `min(18, …)` was on a day: an athlete doing 12k steps and
// 600 kcal in one hour raws out at 13.3 and was recorded as 6 — the same as a brisk 45-minute
// walk. The knee sits at 4 (about 7,200 steps in an hour), so an ordinary hour is untouched and
// only a genuinely hard one compresses, toward 9 rather than stopping at 6.
const HOUR_KNEE = 4, HOUR_MAX = 9;
const softCapHour = (raw) => softCap(raw, HOUR_KNEE, HOUR_MAX);

// THE ONE ACTIVITY MODEL, shared by the headline and the 24h curve.
//
// They used to compute this differently and that is why they diverged: the curve summed per-hour
// buckets (clamped at 6 each) while the headline worked from whole-day totals with no per-hour
// limit at all, so on a hard day the headline charged 28 where the curve could only deliver ~21
// and the endpoint pin absorbed the difference in the last few pixels. The old hard `min(18, …)`
// hid it because both sides saturated on exactly 18; a soft cap never saturates, so it surfaced.
//
// Targeting `bb.activityDrain` from the curve WAS TRIED and made it worse — it forces 7/hour
// through a 6/hour model, so the line falls further and the pin corrects more (3 points -> 11 on
// the same fixture). The fix has to be a shared MODEL, not a shared answer.
//
// STEPS BEFORE THE ESTIMATED WAKE PROVE YOU WERE ALREADY UP — the mirror of the bedtime gate in
// computeBodyBatteryTimeline. The 07:00 anchor is a GUESS, used whenever no watch recorded a
// sleep window (every phone-only user, every night). Both models start their day there, so an
// early riser's 05:30 gym session and a night-shift worker's entire shift fell outside the day
// they belonged to: the headline charged nothing for them and the curve never drew them.
//
// Same asymmetry the bedtime gate states: steps can prove you were AWAKE, never that you were
// asleep. So this only ever moves the anchor EARLIER, only within today, and only when the anchor
// is an estimate in the first place — a real HealthKit window is measured, and beats a guess.
// THE ONE TEST FOR "IS THIS SLEEP WINDOW TRUSTWORTHY". Both Body Battery models decide where your
// day starts, and they used to decide it DIFFERENTLY: the curve ran the full battery of checks
// below, while the headline accepted any `sleepEnd` inside 20h — no start, no ordering, no span
// sanity. So a corrupt window sent them to different anchors and they reported different days.
// Measured on the same store (heavy activity 08:00-10:00, read 20:30):
//
//   window 23:00 -> 11:00 claiming 7.5h sleep   headline 77, chart 56   gap 21
//   sleepEnd present with no sleepStart          headline 77, chart 56   gap 21
//   sleepEnd BEFORE sleepStart                   headline 62, chart 56   gap  6
//
// The headline was the flattering side every time: it believed a late wake, so it charged fewer
// awake hours AND excluded the morning's activity from its window. Trusting it is the failure —
// the checks are right, only one of the two was running them.
//
// Defence in depth for a bad window already written to the store: before pickSleepBlock existed,
// an evening nap merged with last night could persist as "7am -> 8pm", and it would keep driving
// both models until the next HealthKit sync overwrote it. Length alone can't catch that (13h is
// not obviously absurd, and night-shift sleep is legitimately a daytime block) — but a MERGED
// window is always far longer than the sleep it claims to contain, so cross-check the two. A real
// night is its sleep hours plus a little tossing and turning; 13h of window around 7.5h of sleep
